(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c61"]=[{"id":"00008548","register_sub_id":"101","register_pk":"134944","name":"日下家住宅内蔵","kana":"くさかけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29697986,"lng":134.90704737,"geo_status":"db","era":"弘化3年（1846）／大正後期改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0495","desc":"主屋の南面に蔵前を介して続く。南北棟の切妻造桟瓦葺、置屋根。桁行六・〇メートル梁間五・〇メートルの二階建土蔵。上部漆喰仕上げとし、腰をモルタル洗い出し、その下部を根巻石とする。西面に特徴的な窓を上下に穿ち、庭園景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008548"},{"id":"00008556","register_sub_id":"101","register_pk":"134952","name":"日下家住宅厩","kana":"くさかけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29719398,"lng":134.90661912,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積16㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0503","desc":"敷地の西北隅、大正蔵の西に位置する。東西棟の切妻造桟瓦葺で、北面に下屋を付設。桁行三・九メートル梁間四・一メートルの土蔵造二階建。一階に牛を飼い、二階は使用人の部屋として使われた。内・外壁とも中塗仕上げ。質朴な雰囲気をもつ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008556"},{"id":"00008562","register_sub_id":"101","register_pk":"134958","name":"日下家住宅裏門","kana":"くさかけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29720984,"lng":134.90718483,"geo_status":"db","era":"天保10年(1839）","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0509","desc":"敷地東面の北寄り、新居と精米所の間に位置する。南北棟の桟瓦葺、桁行三・〇メートルで、南に両開戸をたて、北に潜りを開ける。本柱上に冠木を載せ、前後に腕木を三通り架し、軒桁を支持し、軒天井を張る。一軒疎垂木。敷地背面に品格のある佇まいをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008562"},{"id":"00012769","register_sub_id":"101","register_pk":"367672","name":"日下家住宅表門","kana":"くさかけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘一丁目64","lat":34.82714194,"lng":135.40227583,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、間口1.9m","structure_material":"コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 704","desc":"敷地東南隅に建つ。コンクリート製、高さ0・7メートル、角形の門柱を間口1・9メートルで立て、両脇に袖塀を付す。玉石洗出し仕上で、下端には鉄平石を巾木状に張る。門扉を設けない小ぶりで簡明な門で、近代住宅らしい明るく開放的な表構えを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012769"},{"id":"00008560","register_sub_id":"101","register_pk":"134956","name":"日下家住宅表門","kana":"くさかけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29714111,"lng":134.90661383,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.4m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0507","desc":"厩と炭小屋の間に南北棟で建つ。間口二・四メートルの一間薬医門、南北に塀を付け、南に潜りを開ける。切妻造桟瓦葺。本柱上に冠木を載せ、前後に男梁を架け、舟肘木を介して束が棟木を支持し、一軒疎垂木とする。簡明な意匠ながら、欅材を用い、風格のある門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008560"},{"id":"00008563","register_sub_id":"101","register_pk":"134959","name":"日下家住宅木塀","kana":"くさかけじゅうたくきべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29696283,"lng":134.90655588,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長9.3m、石垣付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0510","desc":"表門の西南、炭小屋西の庭の北・西辺を区画する。石垣上に建ち、折れ曲がり延長九・三メートルを測る。土台を置き、方柱をたて、貫を通し、木柵状に造る。上部に腕木を通し、軒桁を持ち出し、一軒疎垂木を配る。桟瓦葺。正面入口に穏やかな風情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008563"},{"id":"00008551","register_sub_id":"101","register_pk":"134947","name":"日下家住宅客用風呂","kana":"くさかけじゅうたくきゃくようふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29706181,"lng":134.90679623,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0498","desc":"主屋の主座敷西方に南北棟で建つ。桁行三・六メートル梁間三・二メートルの木造平屋建、入母屋造桟瓦葺。北寄りに便所、南に風呂や脱衣場を配する。扇垂木や桁に磨丸太、網代の装飾を付ける建具を用い、大きく円窓を開けるなど、数寄屋風意匠が各所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008551"},{"id":"00008553","register_sub_id":"101","register_pk":"134949","name":"日下家住宅旧日下林業事務所","kana":"くさかけじゅうたくきゅうくさかりんぎょうじむしょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29720191,"lng":134.90676451,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積55㎡","structure_material":"土蔵造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0500","desc":"旧帳場の西に東西棟で建つ。切妻造桟瓦葺の土蔵造。桁行九・四メートル梁間五・九メートル。南面正面は中央に玄関を設け、東に縦長の窓を三ヶ所、西に庇付窓を開ける。玄関は庇を出し、両脇に円柱を飾る。昭和前期の洋風事務所の雰囲気をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008553"},{"id":"00008552","register_sub_id":"101","register_pk":"134948","name":"日下家住宅旧帳場","kana":"くさかけじゅうたくきゅうちょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29720456,"lng":134.90685968,"geo_status":"db","era":"江戸末期／明治中期・昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0499","desc":"主屋の西北に位置する。桁行七・一メートル梁間五・九メートルの木造二階建。東西棟の切妻造桟瓦葺。一階は六畳と三畳を各二室、二階は六畳二室でトコを構える。南面は黄色大津壁の真壁とし、二階に窓を開け、一階に腰高の格子をたて込み、素朴な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008552"},{"id":"00008550","register_sub_id":"101","register_pk":"134946","name":"日下家住宅金毘羅社","kana":"くさかけじゅうたくこんぴらしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29692646,"lng":134.90678354,"geo_status":"db","era":"天保14年(1843）／江戸末期移築","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.43㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0497","desc":"主屋の南面に広がる庭園の西南に位置する。浜縁付の一間社流造で、正面に千鳥破風と軒唐破風を付ける。檜皮葺。身舎は出組、向拝は三斗を二段に組み、中備に龍を飾る。正面は二軒繁垂木で、唐破風には組入天井を張る。良材を用いた丁寧な造りで、彫物も秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008550"},{"id":"00008549","register_sub_id":"101","register_pk":"134945","name":"日下家住宅座敷","kana":"くさかけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29699836,"lng":134.90716368,"geo_status":"db","era":"弘化3年（1846）／明治23年頃改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0496","desc":"主屋の東南に位置する。東西棟の入母屋造桟瓦葺。南側庭園に向かい、八畳三室を東西に並べ、南面西端に式台、そこから東面にかけて榑縁や濡縁をまわし、主屋との間に化粧ノ間や洗面所を配する。数寄屋風意匠の庇を付けるなど、瀟洒な座敷建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008549"},{"id":"00012768","register_sub_id":"101","register_pk":"367671","name":"日下家住宅主屋","kana":"くさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市切畑字長尾山2-136","lat":34.84947778,"lng":135.33003778,"geo_status":"db","era":"昭和2年頃／昭和20年代・同60年・平成11年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積157㎡","structure_material":"木造2階一部3階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 703","desc":"阪急雲雀丘花屋敷駅北側の住宅地にあり、主屋は東斜面を造成した敷地中央に建つ。木造二階一部三階建、急勾配で切妻造洋瓦葺の東妻を正面とし、正面北半に硝子張の温室を附属する。外観洋風・内部和洋折衷の郊外住宅で昭和前期の都市中間層の暮らしを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012768"},{"id":"00008545","register_sub_id":"101","register_pk":"134941","name":"日下家住宅主屋","kana":"くさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29708031,"lng":134.9069707,"geo_status":"db","era":"寛政11年(1799）／明治中期・大正後期・昭和10年頃改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造2階建、瓦葺、建築面積316㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0492","desc":"敷地中央に西面して建つ。切妻造桟瓦葺、周囲に下屋をまわす。間口二〇メートルと規模が大きく、北に土間を設け、床上は三列各三室で、三方に縁をまわす。土間からオオヒロマにかけて吹抜けとし、数段の貫を通す豪快な小屋組を見せる。大規模な農家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008545"},{"id":"00008547","register_sub_id":"101","register_pk":"134943","name":"日下家住宅新居","kana":"くさかけじゅうたくしんきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.2971649,"lng":134.90720069,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0494","desc":"炊事場の東に続く東西棟の建物。桁行八・三メートル梁間六・五メートルの木造平屋建、入母屋造桟瓦葺で、南面に寄棟造の角屋を付ける。北側二室にトコや書院などを構える。東側は通りに面し、高い石垣上に建ち、窓に外縁を付けて、趣のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008547"},{"id":"00008546","register_sub_id":"101","register_pk":"134942","name":"日下家住宅炊事場","kana":"くさかけじゅうたくすいじば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29716755,"lng":134.90708966,"geo_status":"db","era":"江戸後期／大正後期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0493","desc":"主屋東面に付く東西棟の建物。切妻造桟瓦葺、桁行一〇メートル梁間七・五メートルの木造平屋建。北に土間、南に廊下、その間に台所や食堂、風呂などを配する。台所は中央に調理台を置き、風呂にはモザイクタイルを貼るなど、近代的な生活空間が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008546"},{"id":"00008557","register_sub_id":"101","register_pk":"134953","name":"日下家住宅炭小屋","kana":"くさかけじゅうたくすみごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29707767,"lng":134.90663762,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積15㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0504","desc":"寶蔵の西に位置する。南北棟の入母屋造桟瓦葺。桁行三・九メートル梁間三・七メートルの木造二階建。一、二階とも一室で、二階東面には大きく窓を開ける。西・北面の外壁は大壁造の中塗仕上げとし、門を挟んで建つ厩とともに重厚な表構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008557"},{"id":"00008554","register_sub_id":"101","register_pk":"134950","name":"日下家住宅大正蔵","kana":"くさかけじゅうたくたいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29719927,"lng":134.90667727,"geo_status":"db","era":"大正後期／昭和14年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0501","desc":"旧日下林業事務所の西に東西棟で建つ。桁行六・九メートル梁間五・九メートルの二階建土蔵、切妻造桟瓦葺の置屋根。一階の東寄りは事務所の書庫等として利用。南面は上部に矩形の窓、下部に出入口を穿ち、出入口の鳥居型の上部には特徴的な鏝細工を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008554"},{"id":"00008555","register_sub_id":"101","register_pk":"134951","name":"日下家住宅寶蔵","kana":"くさかけじゅうたくたからぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29706709,"lng":134.90673808,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0502","desc":"客用風呂の西に東西棟で建つ。桁行七・九メートル梁間五・九メートルの二階建土蔵、切妻造桟瓦葺の置屋根。切石積基礎上に建ち、中塗の土壁。内部は一、二階とも一室で、壁板張と丁寧に仕上げる。北面に鳥居型枠の窓を三ヵ所開け、変化のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008555"},{"id":"00012770","register_sub_id":"101","register_pk":"367673","name":"日下家住宅中門","kana":"くさかけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘一丁目65","lat":34.82714194,"lng":135.40227583,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、間口2.1m","structure_material":"コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 705","desc":"表門と主屋をつなぐ階段状の通路の中間地点にある。コンクリート製、高さ2・1メートル、角形の門柱を間口2・1メートルで立てる。洗出し仕上を基調として、柱身に鉄平石の切石を市松模様に張り、柱頂に灯具を載せるなど主屋正面の構えを華やかに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012770"},{"id":"00008561","register_sub_id":"101","register_pk":"134957","name":"日下家住宅中門","kana":"くさかけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29706709,"lng":134.90685968,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口1.2m、渡廊下付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0508","desc":"主屋と客用風呂の間に位置し、通路と庭園とを区画する。間口一・二メートル梁間一・〇メートルの門で、東西に渡り廊下が続く。東西棟の切妻造桟瓦葺で、渡り廊下より棟を高くする。一軒半繁垂木の化粧屋根裏で、床に黒石を貼る。軽快な意匠になる庭門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008561"},{"id":"00008564","register_sub_id":"101","register_pk":"134960","name":"日下家住宅土塀","kana":"くさかけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29685001,"lng":134.90695675,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長88m、石垣付","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0511","desc":"敷地南面から東面南半に延びる土塀。東面は自然石積石垣上、南面は自然石基礎上に造られ、総延長八八メートル、高さ一・八～二・三メートル。上部に腕木を前後に出し、疎垂木を配り、桟瓦を葺く。庭側や一部外側に漆喰が残る。落ち着きのある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008564"},{"id":"00012771","register_sub_id":"101","register_pk":"367674","name":"日下家住宅東門","kana":"くさかけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘一丁目64","lat":34.82714194,"lng":135.40227583,"geo_status":"db","era":"昭和20年代","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"コンクリート造、間口1.3m","structure_material":"コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 706","desc":"敷地東面の南寄りにある。コンクリート製、高さ1・2メートル、角形の門柱を間口1・3メートルで立て、両開きの鉄扉を備える。乱形石張仕上で、内外の地面も乱形石張とする。前庭の一部をなす通用門で、庭木とともに住宅地の街路景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012771"},{"id":"00008558","register_sub_id":"101","register_pk":"134954","name":"日下家住宅物置","kana":"くさかけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市山東町粟鹿字西谷2097他","lat":35.29699572,"lng":134.90659533,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積46㎡、門及び石垣付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0505","desc":"炭小屋南から西に延び、矩折れに南に曲がり、通り沿いを南へ続く。東西棟は桁行九・一メートル梁間一・六メートル。南北棟は門を挟み、桁行計一三メートル梁間二・三メートル。桟瓦葺。庭側を開放、通り側を石垣上に中塗仕上げの大壁とし、敷地構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008558"},{"id":"00012772","register_sub_id":"101","register_pk":"367675","name":"栗原家住宅主屋","kana":"くりはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘一丁目67","lat":34.82714194,"lng":135.40227583,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺一部金属板葺、173㎡","structure_material":"木造平屋一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 707","desc":"阪急雲雀丘花屋敷駅北側の住宅地に建つ。南下りの敷地をいかし、居間や客間を配した南正面の南北棟の背面に個室を配した東西棟を段違いに連ねた立体的な構成とする。欧州の山荘風の独創的な外観で、多様な趣向の住宅が混在する景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012772"},{"id":"00004175","register_sub_id":"101","register_pk":"105165","name":"桑田家住宅主屋","kana":"くわたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷800","lat":35.16696408,"lng":134.79571923,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0170","desc":"生野銀山盛期に役人宅として利用されていた。西を正面とし，主体部は木造つし２階建，入母屋造，平入，桟瓦葺で，周囲に下屋庇を廻し，南西に式台玄関を備えた平屋建の座敷部が接続する。全体に丁寧なつくりで，規模も大きく，地域の象徴的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004175"},{"id":"00004176","register_sub_id":"101","register_pk":"105166","name":"桑田家住宅土蔵","kana":"くわたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷800","lat":35.16705076,"lng":134.79568602,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積15㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0171","desc":"主屋の北西にある。切石積の基礎上に建つ切妻造，平入，桟瓦葺の２階建土蔵で，東面に扉口を開き，下屋庇を設ける。外壁は軒裏まで漆喰塗とし，北妻は縦板で覆うが，南妻の１・２階には整然と庇付の窓を並べる。敷地角地にあり，町並景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004176"},{"id":"00004177","register_sub_id":"101","register_pk":"105167","name":"桑田家住宅門及び塀","kana":"くわたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷800","lat":35.1669535,"lng":134.79561114,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.6m、塀延長30m","structure_material":"木造","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0172","desc":"主屋正面，敷地西辺の北寄りに建つ門は，切妻造，桟瓦葺の１間腕木門形式で，両側には潜戸を備える。西辺の土塀は漆喰塗で，門近くには武者窓風の格子窓を設ける。北辺の土塀は腰を縦板で覆う。屋敷の西辺と北辺を区画するとともに，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004177"},{"id":"00008745","register_sub_id":"101","register_pk":"149466","name":"上月家住宅表門","kana":"こうづきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.8436151,"lng":134.69801218,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、銅板葺、間口2.3m、左右潜戸付","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0520","desc":"敷地南辺の中央に、道路から少し引いて建つ。1間薬医門で、切妻造銅板葺。節くれ立った檜丸太を本柱とし、母屋まで延ばし、母屋と楣間に土壁を塗り、正面側には欄間を飾る。一軒疎垂木の化粧屋根裏天井で、御影石の4半敷。数寄屋風意匠の穏やかな表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008745"},{"id":"00008740","register_sub_id":"101","register_pk":"149461","name":"上月家住宅北離座敷","kana":"こうづきけじゅうたくきたはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84394515,"lng":134.69817452,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0515","desc":"主屋の北に渡り廊下を介して建つ。木造平屋建、建築面積54㎡。南北棟の入母屋造桟瓦葺、軒先を銅板葺とする。18畳広間と、南・西面にまわる榑縁からなり、広間にはトコや棚、付書院を構える。檜4方柾材の柱など良材を贅沢に使い、内部意匠も凝ったつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008740"},{"id":"00008739","register_sub_id":"101","register_pk":"149460","name":"上月家住宅主屋","kana":"こうづきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84379837,"lng":134.69815856,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積223㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0514","desc":"敷地の中央に位置する。東西棟の入母屋造桟瓦葺、木造2階建を中心に、東に平屋の台所や居間、その南に入母屋造の玄関や洋間を張り出す。建築面積223㎡。真壁造で、広く開口部をとり、周囲の庭園を望む。屋根は緩い起りをもち、穏やかな佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008739"},{"id":"00008742","register_sub_id":"101","register_pk":"149463","name":"上月家住宅茶室","kana":"こうづきけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84365797,"lng":134.6979033,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0517","desc":"庭園の南西隅に建つ。深い土庇を出す入母屋屋根を主棟とし、切妻造の水屋を北に付ける。銅板葺で棟近くに桟瓦を葺く。土壁で南・西面の腰に杉皮を張り、東面に窓や躙口を開ける。トコ柱を孟宗竹、トコ框を面皮付の赤松で漆塗とするなど優れた意匠性を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008742"},{"id":"00008744","register_sub_id":"101","register_pk":"149465","name":"上月家住宅土蔵","kana":"こうづきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84400099,"lng":134.69807141,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0519","desc":"北離座敷の西に東西棟で建つ。土蔵造2階建、桁行5.8ｍ梁間3.9ｍ、切妻造妻入本瓦葺。御影石積基礎上に建ち、漆喰仕上げで高く腰竪板を張る。東面に庇をかけ、腰を黒漆喰仕上げとし、出入口を設け、掛子塗の両開戸を吊る。庭園景観の一部をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008744"},{"id":"00008741","register_sub_id":"101","register_pk":"149462","name":"上月家住宅西離座敷","kana":"こうづきけじゅうたくにしはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84378561,"lng":134.69795754,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0516","desc":"主屋南西に太鼓橋を架けて続く。木造平屋建、建築面積56㎡。南北棟の入母屋造桟瓦葺で、軒先を銅板葺とする。座敷飾りのある主座敷と次の間を南北に並べ、3方に榑縁をまわす。庭側は縁に擬宝珠高欄を付け、その下を乱石積とするなど庭を意識した外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008741"},{"id":"00008743","register_sub_id":"101","register_pk":"149464","name":"上月家住宅待合","kana":"こうづきけじゅうたくまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市坊主町37-7","lat":34.84367612,"lng":134.69799424,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0518","desc":"庭園内、茶室の北東に位置する。南北棟の招造で、銅板葺。桁行2.9ｍ梁間0.97ｍ。西面南半部に腰掛、北寄りに物置を設ける。土壁で、東面は腰を杉皮張とする。床は三和土。垂木は丸太と小竹を交互に配し、野地は杉皮を見せる。端正な意匠になる待合。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008743"},{"id":"00008147","register_sub_id":"101","register_pk":"132588","name":"甲南漬資料館（旧高嶋家住宅主屋）","kana":"こうなんつけしりょうかん（きゅうたかしまけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区御影塚町4-100-1","lat":34.71077825,"lng":135.24419289,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積355㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0445","desc":"灘五郷の御影郷に位置する。正面３５ｍの東西に長いＲＣ造２階一部３階建で、南面東半に奥行５．２ｍの木造下屋を付ける。２階窓の庇や蛇腹を壁面にめぐらして、水平性を強調する。西端には、二重のパラボラアーチからなる表現派風デザインの塔屋を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008147"},{"id":"00008750","register_sub_id":"101","register_pk":"149471","name":"小西家住宅北築地塀","kana":"こにしけじゅうたくきたついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.73498717,"lng":135.40221724,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、瓦葺、総延長30m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0525","desc":"敷地北の道路沿い、門の東西に延びる築地塀で、総延長30ｍ。花崗岩を積み基礎とし、外壁は漆喰仕上げ風にモルタル掻き落としとする。躯体は煉瓦造で、上部に瓦を葺く。東側の中央には潜戸を開く。道路境に植栽をして緑を映し込み街路を彩っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008750"},{"id":"00008746","register_sub_id":"101","register_pk":"149467","name":"小西家住宅主屋","kana":"こにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.73485546,"lng":135.40231722,"geo_status":"db","era":"明治44年","year":1911,"year_source":"converted","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0521","desc":"矩形敷地の北寄りに位置する。東西棟の入母屋造桟瓦葺で、下屋をまわし、西に入母屋屋根を突出する。木造つし2階建、建築面積270㎡。北面中央に式台を設け、東に土間、西に居室を配する。大屋根は妻を漆喰で塗り込め、外観に重厚感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008746"},{"id":"00008747","register_sub_id":"101","register_pk":"149468","name":"小西家住宅砂蔵","kana":"こにしけじゅうたくすなぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.73496961,"lng":135.40213294,"geo_status":"db","era":"明治37年頃","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡、祠付","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0522","desc":"敷地の北西隅に建つ。桁行5.9ｍ梁間3.9ｍの土蔵造2階建。東西棟の切妻造本瓦葺。南面出入口に深い桟瓦葺庇を付け、その西寄りに祠を安置する。切石積基礎で、漆喰仕上げとし、正面以外は腰に竪板を張る。角地における重要な景観要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008747"},{"id":"00008748","register_sub_id":"101","register_pk":"149469","name":"小西家住宅納屋","kana":"こにしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.73477555,"lng":135.40247377,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0523","desc":"敷地の東辺、主屋東に南北棟で建つ。木造平屋建、桁行15ｍ梁間6.9ｍ、切妻造桟瓦葺。西面の南半部は深く吹放ちとし、一軒疎垂木の化粧屋根裏を見せる。柱は方柱で、壁は漆喰仕上げ。南妻は板張。南面に広がる畑地と調和のある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008748"},{"id":"00008751","register_sub_id":"101","register_pk":"149472","name":"小西家住宅西石垣","kana":"こにしけじゅうたくにしいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.73475648,"lng":135.4021115,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長50m","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0526","desc":"敷地西辺、水路沿いに、敷地北西隅から南西隅まで延び、一部は砂蔵の基礎を構成する。上部に笠石を載せる石造で、延長50ｍを測る。横長の切石を五段に積むが、場所により上下で施工の違いが見られる。丁寧に施工された花崗岩の石垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008751"},{"id":"00008749","register_sub_id":"101","register_pk":"149470","name":"小西家住宅門","kana":"こにしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市七松町2-249他","lat":34.7349794,"lng":135.4023107,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.8m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"28 － 0524","desc":"敷地北辺の中央に位置する。桁行3.8ｍ梁間3.0ｍ、切妻造桟瓦葺。中央に幅2.4ｍの門口を開き、両開戸を吊る。その両脇と、妻面に袖壁を設け、東妻壁前方に潜戸を開く。男梁を五通りに出し、軒天井を張り、疎垂木を配る。良材を用いた堅実な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008749"},{"id":"00010861","register_sub_id":"101","register_pk":"201696","name":"コヤノ美術館西脇館（旧藤井家住宅）衣装蔵","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）いしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.01358,"lng":134.954322,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0631","desc":"衣装類を収蔵した、漆喰塗の土蔵造二階建。東西棟の桟瓦葺で、南面に下屋を設けて扉口二箇所を配する。上下階とも厚い壁で東西に二分され、東が登梁形式、西が弓状の梁を用いた和小屋になる。主屋の北西で中庭を囲って建ち、屋敷北辺の景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010861"},{"id":"00010862","register_sub_id":"101","register_pk":"201697","name":"コヤノ美術館西脇館（旧藤井家住宅）表門及び塀","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）おもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.01358773,"lng":134.95481759,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"表門 木造、瓦葺、間口2.5m、左右袖塀付 塀 木造、瓦葺、総延長50m","structure_material":"表門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0632","desc":"敷地東面に構える間口二・五メートルの棟門。一軒疎垂木の切妻造で、両側に潜戸付袖塀を付け、背面に控柱を立てる。木造で腰板張の高塀は、折曲り長さが、南八・八メートル、北四一メートルを測る。桟瓦葺屋根を廻らし、調和のとれた屋敷正面の景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010862"},{"id":"00010860","register_sub_id":"101","register_pk":"201695","name":"コヤノ美術館西脇館（旧藤井家住宅）米蔵","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.013509,"lng":134.954762,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積48㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0630","desc":"平屋建の土蔵造、東西棟の切妻造桟瓦葺とし、扉口のある北面には庇をかける。北面と東西両妻面は腰を人造石洗出し、上部を漆喰塗とするが、南面は上部まで竪板覆で、内部の壁は丁寧な羽目板張である。敷地東面の南にあって、屋敷の正面景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010860"},{"id":"00009807","register_sub_id":"101","register_pk":"195636","name":"コヤノ美術館西脇館（旧藤井家住宅）主屋","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.01350142,"lng":134.95453834,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積351㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0565","desc":"敷地の中央に東面して建つ。緩く起らせた入母屋造桟瓦葺で下屋を廻す。南寄りを土間とし、床上部は九間取で三方を縁とする。座敷の欄間には、鉄橋である天神橋をはじめとする大阪の情景を透彫とするなど、近代的な趣向を凝らす、上質で開放的な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009807"},{"id":"00010864","register_sub_id":"101","register_pk":"201699","name":"コヤノ美術館西脇館（旧藤井家住宅）主屋南脇門及び塀","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）しゅおくみなみわきもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.01338178,"lng":134.95464242,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"南脇門 木造、瓦葺、間口4.6m 塀 木造、瓦葺、延長39m","structure_material":"南脇門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0634","desc":"主屋南にあり、東面する南脇門は簡明な腕木付の塀中門で、一軒疎垂木の切妻造桟瓦葺。中央を門口、両脇を漆喰塗腰板張とする。塀は高さ約四メートルの木造桟瓦葺、門南端から西に延び、外側竪板覆、内側は土塀風に仕上げる。豪壮な屋敷南辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010864"},{"id":"00010863","register_sub_id":"101","register_pk":"201698","name":"コヤノ美術館西脇館（旧藤井家住宅）庭門及び塀","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）にわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.01357176,"lng":134.9546819,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"庭門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長15m","structure_material":"庭門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0633","desc":"庭門は簡明な一間薬医門で、一軒疎垂木の切妻造桟瓦葺、両側に木造で腰板張の塀を延ばし、庭側には石製控柱を付ける。基礎は丁寧な切石積。主屋中央と表門北を結び、座敷前庭と玄関までの空間を区切る門塀で、雄大な屋敷に相応しい前面空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010863"},{"id":"00010859","register_sub_id":"101","register_pk":"201694","name":"コヤノ美術館西脇館（旧藤井家住宅）離れ","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.013503,"lng":134.954173,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0629","desc":"主屋西方に廊下で接続する。二階建、南北棟の入母屋造桟瓦葺で屋根に起りを付け、庇を銅板葺とする。各階は中庭側の東を八畳二室、西を六畳と階段室とした平面で、吟味した多彩な銘木を用い異なる座敷飾にまとめるなど、内外とも当時の造形の指向をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010859"},{"id":"00010857","register_sub_id":"101","register_pk":"201692","name":"コヤノ美術館西脇館（旧藤井家住宅）洋館","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）ようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.013442,"lng":134.954334,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0627","desc":"主屋西側、離れに続く廊下東半の南に位置する。東の水屋付応接間と書斎からなる平屋建で、屋根は東西棟の寄棟造、桟瓦葺である。ドイツ壁風仕上げの外壁、縦長の上下窓、独特な幾何紋様の格縁天井の応接間、丁寧な漆喰塗の書斎など、質の高い洋風意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010857"},{"id":"00010858","register_sub_id":"101","register_pk":"201693","name":"コヤノ美術館西脇館（旧藤井家住宅）浴室及び便所棟","kana":"こやのびじゅつかんにしわきかん（きゅうふじいけじゅうたく）よくしつおよびべんじょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県西脇市市原町字広畑ケ139","lat":35.013426,"lng":134.954215,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0628","desc":"主屋西側、離れに続く廊下西半の南にある。木造平屋建、出入りのある平面で、西に外便所を突出し、桟瓦葺屋根も変化に富む。鏡付ガラス戸のある洗面所、気抜付で装飾タイル張の浴室及び脱衣室、火灯窓付の便所などからなる。上質で類例の少ない生活施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010858"},{"id":"00009805","register_sub_id":"101","register_pk":"195634","name":"坂井家住宅北面東棟門及び塀","kana":"さかいけじゅうたくきためんひがしとうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区山本通3-1-7他","lat":34.69877362,"lng":135.18494348,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"東棟門 間口1.4m、鉄製門扉付 塀 煉瓦造、総延長8.6m","structure_material":"東棟門 間口1.4m","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0563","desc":"主屋の北面道路沿いに折曲がりにのびる塀と門で、東西各棟の前庭を画す。西棟側は東棟側よりやや荒いモルタル塗ドイツ壁仕上げとし、区別する。東棟門は当初の扉が残り、鉄製で上部を竪格子とし、頂部は曲線を組み合わせた形とする。主屋正面の景観を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009805"},{"id":"00009804","register_sub_id":"101","register_pk":"195633","name":"坂井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区山本通3-1-7他","lat":34.69874149,"lng":135.18498988,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、スレート葺、建築面積182㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0562","desc":"北野町西端、六甲山南麓の斜面地に北面する。中央壁を境に二階建住宅を二戸建てる形式で、シンメトリーからやや崩した平面および外観を持つ。外壁はモルタル塗ドイツ壁仕上げで、玄関脇の一室を和室とする他は洋間とする。当時の外国人向けの賃貸住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009804"},{"id":"00009806","register_sub_id":"101","register_pk":"195635","name":"坂井家住宅南面塀","kana":"さかいけじゅうたくみなみめんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区山本通3-1-7他","lat":34.69868796,"lng":135.18503628,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0564","desc":"主屋の南、敷地南端の石垣上に建ち、居間南面に広がる庭園を区画する。延長一八メートルの煉瓦造モルタル塗の塀で、等間隔に表す柱形の間を壁とし、壁頂部は逆ハンチの形状として意匠上の工夫を施す。傾斜地に建つ住宅の南面外観を、高い石垣とともに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009806"},{"id":"00004174","register_sub_id":"101","register_pk":"105164","name":"佐藤家住宅別邸","kana":"さとうけじゅうたくべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷746","lat":35.1672037,"lng":134.79447844,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0169","desc":"木造つし２階建，切妻造，平入で，通りに南面して建つ。桟瓦葺屋根は置屋根式で，棟に切妻造の煙出屋根を設ける。外壁は漆喰塗の大壁造で，１階玄関横に繊細な出格子を設け，正面２階の窓は東側に寄せて２つ並べる。江戸後期の町家の佇まいをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004174"},{"id":"00014402","register_sub_id":"101","register_pk":"511391","name":"澁谷家住宅主屋","kana":"しぶやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県豊岡市但東町中山字柳ヶ坪147","lat":35.50151944,"lng":134.99673611,"geo_status":"db","era":"弘化3年(1846)頃／文久３年（１８６３）・明治３５年・平成３年改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積197㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"28 - 0789","desc":"豊岡と宮津を結ぶ街道沿い絹織物産地に所在する旧家の養蚕民家。越屋根と虫籠窓を設けたつし二階建、座敷側入母屋造、土間側切妻造で平入桟瓦葺とする。六間取平面で、表座敷を付書院床構え、ミセノマを帳場とする。本陣や郵便局に供した地域の中心的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014402"},{"id":"00013850","register_sub_id":"101","register_pk":"507809","name":"島中家住宅主屋","kana":"しまなかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.73288056,"lng":135.39158056,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0753","desc":"武庫川の左岸に位置。入母屋造桟瓦葺で東を落棟として他三方に下屋を廻す。軒裏まで漆喰で塗込め、つし二階に虫籠窓を開ける。中央を土間、東を納戸や台所とし、西は二列五室で南西を座敷として前庭に臨み式台玄関を付す。桁行二〇メートルを測る雄大な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013850"},{"id":"00013851","register_sub_id":"101","register_pk":"507810","name":"島中家住宅蔵","kana":"しまなかけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.732975,"lng":135.3915,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0754","desc":"主屋の北面に接続。桁行三間梁間二間、土蔵造二階建で切妻造本瓦葺の置屋根を載せる。漆喰で鉢巻まで塗込め、他は全面に竪板を張る。大戸片引及び格子戸引違を建て戸口とし、主屋奥の間から出入する。内部は一、二階とも一室。隣接する蔵のうちでは規模最大。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013851"},{"id":"00013855","register_sub_id":"101","register_pk":"507814","name":"島中家住宅仕切塀","kana":"しまなかけじゅうたくしきりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.73279444,"lng":135.39145833,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、延長11m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0758","desc":"主屋南西の前庭を囲う塀。布石の上に柱を半間毎に立て、頂部に腕木を出し桟瓦葺を受ける。南面は、外面は腰は竪板張で上部漆喰仕上とし、内面は巾木に漆喰仕上とする。西面は腰高の竪板張上部に格子欄間を設ける。各面で意匠を違えて前庭内外の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013855"},{"id":"00013852","register_sub_id":"101","register_pk":"507811","name":"島中家住宅中蔵","kana":"しまなかけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.73296111,"lng":135.39156944,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積15㎡","structure_material":"土蔵造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0755","desc":"内蔵の東に並び建つ。桁行二間半梁間一間半土蔵造平屋建切妻造本瓦葺。軒裏まで漆喰で塗上げ垂木形をみせ、竪板を張り、北面中央に窓を開ける。南面に大戸片引及び格子戸引違を建て戸口とし、曲木の持送で庇を受ける。内部は一室。連続する蔵景観の一画形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013852"},{"id":"00013854","register_sub_id":"101","register_pk":"507813","name":"島中家住宅納屋","kana":"しまなかけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.732975,"lng":135.39167222,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積5.9㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0757","desc":"東蔵の東に建つ。桁行一間半梁間一間、平屋建切妻造桟瓦葺で、真壁造漆喰仕上及び竪板張。東面は開放で東蔵の外壁を共有する。南面に板戸片引を建てて戸口とし、内部は土間の一室で、妻の柱が棟木を受ける。大中小の蔵に寄り添うように建つ、小規模な納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013854"},{"id":"00013853","register_sub_id":"101","register_pk":"507812","name":"島中家住宅東蔵","kana":"しまなかけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市大庄北二丁目126","lat":34.73296111,"lng":135.39161944,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積12㎡","structure_material":"土蔵造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0756","desc":"中蔵の東に並び建つ。桁行二間梁間一間半、土蔵造平屋建切妻造本瓦葺。軒裏まで漆喰で塗上げ垂木形をみせ、竪板を張り、北面中央に窓を開く。南面に大戸片引、格子戸引違を建て戸口とし庇を架ける。大中小の土蔵が建ち並ぶ姿が特徴的な敷地北辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013853"},{"id":"00005001","register_sub_id":"101","register_pk":"105991","name":"正司家住宅洋館","kana":"しょうじけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘2-5-22","lat":34.828011,"lng":135.399094,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積251㎡","structure_material":"木造2階一部地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0195","desc":"阪急宝塚線沿線の住宅地に建つ和館洋館併存住宅の洋館。斜面地で南側一部に地階を設けた木造２階建で，ベル形ドーム屋根や袴腰形屋根，軒下のタイル市松模様張など大正期特有のジャーマンセセッションの秀作。設計は宝塚ホテルなどを手がけた古塚正治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005001"},{"id":"00005002","register_sub_id":"101","register_pk":"105992","name":"正司家住宅和館","kana":"しょうじけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘2-5-22","lat":34.828094,"lng":135.399277,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0196","desc":"洋館の東方に建つ。主体部は入母屋造，桟瓦葺の木造平屋建で，洋館寄りの南側には縁側及び床・棚・書院付きの８畳座敷と８畳次の間を配し，中廊下を介して北に玄関を突き出す。東側はもと茶の間と台所等。低平なつくりで洋館との量的なバランスを巧みにとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005002"},{"id":"00004161","register_sub_id":"101","register_pk":"105151","name":"静思館（旧冨田家住宅）衣装蔵","kana":"せいしかん（きゅうとみたけじゅうたく）いしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89432163,"lng":135.37607742,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0156","desc":"屋敷地の北辺，中蔵の東に建つ，方２間の土蔵造２階建。屋根は切妻造，桟瓦葺で，南面中央に戸口を設け，桁行全長に瓦庇を付す。床下換気口のある切石積基壇に建ち，外壁は白漆喰塗で腰を縦羽目板張とする。西隣の中蔵と意匠を揃え，統一感のある構えである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004161"},{"id":"00004171","register_sub_id":"101","register_pk":"105161","name":"静思館（旧冨田家住宅）井戸小屋","kana":"せいしかん（きゅうとみたけじゅうたく）いどごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89358355,"lng":135.37632107,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積2.1㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0166","desc":"表門の南方，道路からの導入路の途中に番小屋と並んで設けた井戸を囲む上屋。桁行１間半，梁間半間で，東半を南に開放して井戸枠を納め，西半をポンプ室とする。壁は縦羽目板張で，北の通路側を棟高まで壁とし，棟に瓦を置いた波形鉄板葺の招き屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004171"},{"id":"00004159","register_sub_id":"101","register_pk":"105149","name":"静思館（旧冨田家住宅）乾蔵","kana":"せいしかん（きゅうとみたけじゅうたく）いぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.8942774,"lng":135.37594775,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0154","desc":"屋敷地の北西隅に建つ，桁行４間半，梁間２間半の土蔵造２階建。屋根は切妻造，桟瓦葺で，南面の東寄りに戸口を設け，瓦葺庇を付す。床下換気口を開いた切石の基礎に建ち，外壁は白漆喰塗で腰は縦羽目板張。妻側１箇所，平側２箇所の窓上庇を持送りで受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004159"},{"id":"00004157","register_sub_id":"101","register_pk":"105147","name":"静思館（旧冨田家住宅）表門","kana":"せいしかん（きゅうとみたけじゅうたく）おもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89399747,"lng":135.3762076,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡、左右脇塀8.3m付","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0152","desc":"屋敷地の南を限る長屋門。桁行８間，入母屋造，桟瓦葺。弁柄塗の木部に黄大津壁，腰は簓子下見板張である。主門は両開板扉で西に潜戸がつく。主門前に腰高の木柵を設ける。西に門座敷８畳と口の間２畳，東は農具物置。東西に脇塀が続き，西脇塀に戸口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004157"},{"id":"00004169","register_sub_id":"101","register_pk":"105159","name":"静思館（旧冨田家住宅）勝手門","kana":"せいしかん（きゅうとみたけじゅうたく）かってもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89409122,"lng":135.37607693,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、間口4.2m","structure_material":"木造","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0164","desc":"主屋の土間側南西角と道具部屋の南東角を結んで設けた通用門。前庭と裏庭を区画する。切妻造，桟瓦葺で，主屋の庇下に棟を差入れる。中央に両開板扉を釣込み，両脇は塀とし，板扉上端部は木格子を組む。弁柄塗の木部と黄大津壁で周囲の建物と仕上げを揃える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004169"},{"id":"00004166","register_sub_id":"101","register_pk":"105156","name":"静思館（旧冨田家住宅）給水塔","kana":"せいしかん（きゅうとみたけじゅうたく）きゅうすいとう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.894253,"lng":135.37604693,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積9.8㎡、塔屋付","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0161","desc":"主屋の北，中蔵との間にある高架水槽。便所を水洗化するための施設で，井戸水をポンプで汲み上げて貯水した。桁行２間，梁間１間半。内転びの柱を用いた切妻造，桟瓦葺の井戸屋形上に，銅板葺の櫓を掲げて水槽を納める。当地域では先駆的な設備であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004166"},{"id":"00004162","register_sub_id":"101","register_pk":"105152","name":"静思館（旧冨田家住宅）柴部屋","kana":"せいしかん（きゅうとみたけじゅうたく）しばべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89404187,"lng":135.37605747,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0157","desc":"屋敷地の西辺，主屋前庭に東面して建つ，桁行２間半，梁間２間の木造平屋建。屋根は切妻造，桟瓦葺で，腕木で軒桁を受ける。木部は弁柄塗，外壁は黄大津壁で，腰を縦羽目板張とする。戸口は両開の板扉。小建物であるが主屋等と意匠を揃え，前庭の点景となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004162"},{"id":"00004155","register_sub_id":"101","register_pk":"105145","name":"静思館（旧冨田家住宅）主屋","kana":"せいしかん（きゅうとみたけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.894188,"lng":135.376144,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、茅葺、建築面積261㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0150","desc":"屋敷地の中央に南面して建つ。西妻が入母屋造，東妻が切妻造の茅葺屋根，平入で，南面などに瓦庇を付す。内部は西に土間，東に２列６室を配す。東に瓦葺入母屋造の座敷棟と上便所が突出する。小屋組はトラス。農家系の近代和風建築の好例。棟梁は斎藤宗太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004155"},{"id":"00004158","register_sub_id":"101","register_pk":"105148","name":"静思館（旧冨田家住宅）書斎蔵","kana":"せいしかん（きゅうとみたけじゅうたく）しょさいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89402398,"lng":135.376312,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0153","desc":"内庭の南寄り，表門東に建つ。桁行３間梁間２間半，切妻造，桟瓦葺の土蔵造平屋建で，北妻に出入口の庇を付す。外壁は漆喰塗で，腰を縦板張とする。東面と南面に窓を開き，窓上庇は繰形付持送りで受ける。畳敷の鉄板床で，床下にはオンドル風暖房を設備する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004158"},{"id":"00004164","register_sub_id":"101","register_pk":"105154","name":"静思館（旧冨田家住宅）炭部屋","kana":"せいしかん（きゅうとみたけじゅうたく）すみべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89417458,"lng":135.37599003,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0159","desc":"屋敷地の西辺，道具部屋の北に建つ。梁間２間，桁行１０尺の木造平屋建，切妻造，桟瓦葺。正面瓦庇は南に並ぶ道具部屋から一連に造る。弁柄塗の木部と黄大津壁は表門等と共通の仕上げ。軒下小壁に木瓜形の高窓を開くなど，道具部屋と意匠を統一している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004164"},{"id":"00004156","register_sub_id":"101","register_pk":"105146","name":"静思館（旧冨田家住宅）茶室","kana":"せいしかん（きゅうとみたけじゅうたく）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89415092,"lng":135.37632156,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0151","desc":"主屋の南東に位置し，上便所から水屋を介して接続する。入母屋造の桟瓦葺で，軒先を銅板一文字葺とする。茶室は４畳半で，北に地板がつき，西に濡縁の貴人口，東に下地窓をひらく。南の瓦敷土間に立礼席を設け，ガラス窓を開くなど，近代の感覚を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004156"},{"id":"00004163","register_sub_id":"101","register_pk":"105153","name":"静思館（旧冨田家住宅）道具部屋","kana":"せいしかん（きゅうとみたけじゅうたく）どうぐべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89410737,"lng":135.37602375,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0158","desc":"屋敷地の西辺，勝手門を挟んで主奥の西に建つ。木造平屋建，切妻造，桟瓦葺で，梁間２間，桁行３間半の南端１間は落棟の便所とし南妻に瓦葺庇がつく。軒下小壁に木瓜形の高窓を開く。正面瓦庇は北に並ぶ炭部屋と一連に造る。弁柄塗の木部に黄大津壁が鮮やか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004163"},{"id":"00004170","register_sub_id":"101","register_pk":"105160","name":"静思館（旧冨田家住宅）土塀","kana":"せいしかん（きゅうとみたけじゅうたく）どべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89439421,"lng":135.37631178,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土塀、瓦葺、延長98m、裏木戸付","structure_material":"土塀","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0165","desc":"表門の東脇塀の南端に発し，屋敷地の東辺から北辺を囲む土塀。総長約９８ｍ。高さのある石垣の上から立ち上がる。練塀で瓦葺とする。北辺中央やや東寄り，衣装蔵東の裏口は木部を弁柄塗とし，無双窓付の板戸を片引きに建て込む。北辺西端には裏木戸を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004170"},{"id":"00004167","register_sub_id":"101","register_pk":"105157","name":"静思館（旧冨田家住宅）供待ち","kana":"せいしかん（きゅうとみたけじゅうたく）ともまち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.893959,"lng":135.37605858,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積4.2㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0162","desc":"表門の西，西脇塀から戸口を入った内側に建つ。桁行１間半，梁行半間。東面を開放し，西に腰掛を設ける。腰高の鉄筋コンクリート造壁から柱を立て，梁の曲がりを活かして波形鉄板葺の招き屋根を架ける。柱間は全て開放で，小壁は土塗，竹簀の舟底天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004167"},{"id":"00004160","register_sub_id":"101","register_pk":"105150","name":"静思館（旧冨田家住宅）中蔵","kana":"せいしかん（きゅうとみたけじゅうたく）なかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89431017,"lng":135.37602795,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0155","desc":"屋敷地の北辺，乾蔵の東に建つ，桁行２間半，梁間２間の土蔵造２階建。切妻造，桟瓦葺で，南面中央に戸口を設け，桁行全長に瓦庇をつける。床下換気口を開いた切石積の高い基礎上に建ち，外壁は白漆喰塗，腰を縦羽目板張とし，窓上庇を持送りで受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004160"},{"id":"00004168","register_sub_id":"101","register_pk":"105158","name":"静思館（旧冨田家住宅）庭塀","kana":"せいしかん（きゅうとみたけじゅうたく）にわべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.894076,"lng":135.37622269,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、延長13m","structure_material":"木造","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0163","desc":"表門の東端から主屋南面の式台東側に至る瓦葺塀。表門から２間目で鉤の手に折れ，西の前庭と東の内庭を限る。木部の弁柄塗に黄大津壁を取合せ，粗い格子を組んだ窓を開く。腰は前庭側を縦羽目板張，内庭側を杉皮張とし，主屋から３間目に引違いの戸口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004168"},{"id":"00004172","register_sub_id":"101","register_pk":"105162","name":"静思館（旧冨田家住宅）番小屋","kana":"せいしかん（きゅうとみたけじゅうたく）ばんこや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89352863,"lng":135.37637839,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0167","desc":"敷地の南端，街道からの導入路に面して建つ。桁行３間，梁間１間半で，木造平屋建，起りのある切妻屋根を瓦葺とする。西半は入口土間と２畳間に押入，東半を４畳半とし，東妻に濡れ縁を設ける。北妻庇","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004172"},{"id":"00004165","register_sub_id":"101","register_pk":"105155","name":"静思館（旧冨田家住宅）味噌部屋","kana":"せいしかん（きゅうとみたけじゅうたく）みそべや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川辺郡猪名川町上野字町廻22","lat":34.89422198,"lng":135.37596785,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積11㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0160","desc":"屋敷地の西辺，炭部屋の北に建つ。桁行２間，梁間１０尺の土蔵造平屋建，切妻造，桟瓦葺。切石積基礎上に建ち，外壁は白漆喰塗，腰を縦羽目板張とする。東妻の戸口に弁柄塗の板戸を建て込み，瓦庇を腕木で受けるなど，道具部屋，炭部屋と馴染む意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004165"},{"id":"00003892","register_sub_id":"101","register_pk":"104882","name":"千本内海家住宅主屋","kana":"せんぼんうつみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県たつの市新宮町千本1824","lat":34.94301361,"lng":134.49098177,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"28 － 0139","desc":"出雲往来千本宿の本陣で，大庄屋の居宅。主屋は敷地東寄りの中程に建つ。桁行１０間半梁間５間半の規模で，平面は西半を床上部とし，南面西寄りには入母屋屋根を突出させる式台玄関を設ける。屋根は全体を本瓦葺とする。高い格式を誇る上層農家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003892"},{"id":"00003894","register_sub_id":"101","register_pk":"104884","name":"千本内海家住宅土蔵","kana":"せんぼんうつみけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県たつの市新宮町千本1824","lat":34.94308032,"lng":134.49117851,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"28 － 0141","desc":"敷地東端の中程，主屋の北東側に建つ。切妻造，桟瓦葺の２階建土蔵で，東面，北面には上部を残して縦板を張り，南面と西面は漆喰塗とし，軒まで塗込めている。西側には大きく下屋を張り出し，片引の大戸を設ける。大庄屋の屋敷地の景観を今日に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003894"},{"id":"00003893","register_sub_id":"101","register_pk":"104883","name":"千本内海家住宅長屋門","kana":"せんぼんうつみけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県たつの市新宮町千本1824","lat":34.94281345,"lng":134.4909749,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"28 － 0140","desc":"敷地南側東寄りに建ち，出雲往来に面する。中央に表門を開き，西寄りに畳敷の８畳間，東寄りに板敷の男部屋を設ける。屋根は入母屋造桟瓦葺，外壁は下部を縦板張，窓より上部を漆喰塗とする。上層農家の長屋門の好例であり，千本宿の景観を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003893"},{"id":"00005328","register_sub_id":"101","register_pk":"106316","name":"高井家住宅主屋","kana":"たかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加西市北条町横尾127","lat":34.93305448,"lng":134.83791242,"geo_status":"db","era":"嘉永4","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0238","desc":"京・大坂への街道に北面して建ち，桁行６間半，梁間５間の規模とし，木造つし２階建，切妻造，桟瓦葺の塗屋造の平入の町家で，東側を通り土間とし，床上部を整形四間取りとする。正面はつし２階に虫籠窓を付け，１階は出格子を付けるなど通り景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005328"},{"id":"00005329","register_sub_id":"101","register_pk":"106317","name":"高井家住宅土蔵一","kana":"たかいけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加西市北条町横尾127","lat":34.93310676,"lng":134.83783779,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0239","desc":"主屋の西脇の街道沿いに建つ。桁行２間，梁行２間で，土蔵造２階建，切妻造，本瓦葺，平入，置屋根形式で，主屋と廊下で結ばれている。屋根は登り梁を用い，内部を板張りとし，道具蔵として使われている。正面はやや高く腰板を張り，上部を漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005329"},{"id":"00005330","register_sub_id":"101","register_pk":"106318","name":"高井家住宅土蔵二","kana":"たかいけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加西市北条町横尾127","lat":34.93298304,"lng":134.83797645,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0240","desc":"主屋に接してその東側に建つ。桁行３間半，梁間２間の規模で，土蔵造２階建，切妻造，本瓦葺，平入，漆喰塗で，外壁の一部を板張りとする。主屋の土間背後に出入口を付ける。屋根はむくりをもった梁に母屋を置いて造られ，希少な構造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005330"},{"id":"00011369","register_sub_id":"101","register_pk":"209206","name":"髙添家住宅木戸門","kana":"たかぞえけじゅうたくきどもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘山手一丁目148","lat":34.830073,"lng":135.405437,"geo_status":"db","era":"昭和前期","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造、杉皮葺、間口3.8m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"28－0657","desc":"敷地西側の道路際に南北棟で建つ。腕木門の形式をとるが、主柱は出節付の丸太とし、両開の桟唐戸には、下段に木目を砂摺とした鏡板、中段に挽割の柾目板、上段に連子状の板を嵌め、屋根はこけら板を葺いた上に杉皮を葺く。数寄屋意匠をふんだんに用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011369"},{"id":"00011368","register_sub_id":"101","register_pk":"209205","name":"髙添家住宅土蔵","kana":"たかぞえけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘山手一丁目148","lat":34.830139,"lng":135.405686,"geo_status":"db","era":"昭和前期","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"28－0656","desc":"和館の東方に東西棟で建つ。土蔵造二階建で、小屋は登梁形式とする。屋根には本瓦を葺く。二階の南面、西面には採光のための窓が設けられ、窓上部には庇が付く。庇は持ち送りから屋根面まで白漆喰で塗込める。近代の阪神間での郊外型住宅開発の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011368"},{"id":"00011366","register_sub_id":"101","register_pk":"209203","name":"髙添家住宅洋館","kana":"たかぞえけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘山手一丁目148","lat":34.830156,"lng":135.40541,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"28－0654","desc":"丘陵地の一画に所在する花屋敷住宅地に構える。二階建で一階を撞球室、二階を書斎等とする。寄棟造に切妻屋根や玄関ポーチ、出窓を張り出すなど、変化に富んだ外観を持つ。内部も随所にアールデコやセセッションなどの意匠を多用し、本格的な洋館にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011366"},{"id":"00011367","register_sub_id":"101","register_pk":"209204","name":"髙添家住宅和館","kana":"たかぞえけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県宝塚市雲雀丘山手一丁目148","lat":34.830154,"lng":135.405567,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"28－0655","desc":"中央に玄関を設け、玄関北には食堂と台所、東には座敷飾を持つ八畳を設けて縁を廻し、西には旧茶室を配する。八畳間は、磨き丸太を床柱として、黒漆塗の床框とするなど良材を用いる。洋館からの渡廊下は弓型の船底天井とするなど、意匠を凝らした仕様を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011367"},{"id":"00014070","register_sub_id":"101","register_pk":"508330","name":"鷹津家住宅表門及び塀","kana":"たかつけじゅううたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市御国野町深志野字北宅地586","lat":34.82719167,"lng":134.74303889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"表門 木造、瓦葺、間口2.1m、塀 木造、瓦葺、総延長6.1m","structure_material":"表門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0775","desc":"敷地西辺南側に建つ表門で、両脇に敷地に沿う塀を延ばす。切妻造桟瓦葺の棟門で、控柱間と本柱の袖に壁を付す。腕木で出桁として天井を張り、蟇股で棟木を支える。袖壁と桟瓦葺の塀は、真壁白漆喰塗で腰を竪板張とする。旧家の門構えを格式高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014070"},{"id":"00014068","register_sub_id":"101","register_pk":"508328","name":"鷹津家住宅厨及び井戸場","kana":"たかつけじゅううたくくりやおよびいどば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市御国野町深志野字北宅地586","lat":34.82731111,"lng":134.74314167,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0773","desc":"道路沿いの敷地北西外郭に建つ付属屋。平屋建Ｌ字形平面の切妻造桟瓦葺、東西棟の厨と南北棟の井戸場からなる。道路側外壁は漆喰塗、腰は竪板張で、厨東半に通用口を開く。敷地側は厨西半を漆喰塗で腰を竪板張とし他は開放とする。集落の街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014068"},{"id":"00014069","register_sub_id":"101","register_pk":"508329","name":"鷹津家住宅道具蔵","kana":"たかつけじゅううたくどうぐくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市御国野町深志野字北宅地586","lat":34.82725,"lng":134.74308611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積24㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0774","desc":"敷地西辺で井戸場の南に接続して東面する土蔵。二階建、切妻造本瓦葺で、外壁は軒先まで漆喰塗込で鉢巻付、正面腰は七宝形海鼠壁、他は竪板張。正面庇を付し、戸口縁取りを木瓜形にして片引き塗戸を建てる。街路景観を形成すると共に内向きに意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014069"},{"id":"00014067","register_sub_id":"101","register_pk":"508327","name":"鷹津家住宅主屋","kana":"たかつけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市御国野町深志野字北宅地586","lat":34.82721389,"lng":134.74329167,"geo_status":"db","era":"明治27年頃／明治40年増築","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積312㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0772","desc":"江戸後期から代々医師を務める旧家。主屋は敷地中央に南面して建つ二階建入母屋造本瓦葺で、正面に唐破風玄関、四周に下屋、西側に落棟の旧診療所を付す。内部は西を土間、東を六間取で上手表を書院座敷とする。医家の格調高い外観と上質な細部意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014067"},{"id":"00014071","register_sub_id":"101","register_pk":"508331","name":"鷹津家住宅庭門及び塀","kana":"たかつけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市御国野町深志野字北宅地586","lat":34.82714167,"lng":134.74325833,"geo_status":"db","era":"明治40年頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"庭門 木造、瓦葺、間口1.6m、塀 木造、瓦葺、総延長11m","structure_material":"庭門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0776","desc":"主屋前庭を東西に区画する南北棟の門と塀。西側は玄関側の前庭、東側は座敷庭とする。庭門は切妻造桟瓦葺の腕木門で、開き戸と横格子欄間とする。塀は桟瓦葺、真壁黒漆喰塗で腰を竪板張とし、一間毎に名栗材の格子窓を開く。旧家の庭園を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014071"},{"id":"00005000","register_sub_id":"101","register_pk":"105990","name":"宝塚市立中央図書館桜ガ丘資料室（旧松本安弘邸）主屋","kana":"たからづかしりつちゅうおうとしょかんさくらがおかしりょうしつ（きゅうまつもとやすひろてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市桜ガ丘3-45","lat":34.81644733,"lng":135.33759117,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0194","desc":"西宮市との市境近くの住宅地に建つ。寄棟造，Ｓ字瓦葺，木造２階建の洋風住宅で，腰を下見板張とし，ペアの持送りが支持する玄関庇，１枚ガラスの上げ下げ窓，西面のベイウィンドーなどが特徴ある外観をつくる。カリフォルニア大学出身の建築家川崎忍の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005000"},{"id":"00002968","register_sub_id":"101","register_pk":"103958","name":"多木浜洋館主屋","kana":"たきはまようかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市別府町東町174","lat":34.72247059,"lng":134.84650565,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造4階建、銅板葺、建築面積294㎡","structure_material":"木造4階建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0106","desc":"加古川市別府港に注ぐ別府川右岸河口近くに建つ。1階腰を煉瓦積もしくは花崗岩積としたたちの高い木造4階建で、凹凸のある平面形状と勾配を変えた切妻屋根とがつくりだす多彩なシルエットに特徴がある。外装は全面銅板張で、あかがね御殿として広く知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002968"},{"id":"00002969","register_sub_id":"101","register_pk":"103959","name":"多木浜洋館石造門","kana":"たきはまようかんせきぞうもん","category":"住宅","subcategory":"その他工作","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市別府町東町174","lat":34.72246671,"lng":134.84665523,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、間口3.1m、両側石造袖塀5.6m付","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0107","desc":"主屋東北端から敷地北辺に沿って延びる煉瓦塀の中途に建つ。間口は３ｍ規模，胴張りをつけた一本石の柱に石製のまぐさ，大斗，肘木，蟇又等を載せた和風意匠の特異な石造門で，左右に高さ約３ｍ規模，平面１／４円状の石造袖塀を付けて煉瓦塀に接続させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002969"},{"id":"00002970","register_sub_id":"101","register_pk":"103960","name":"多木浜洋館煉瓦塀","kana":"たきはまようかんれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市別府町東町174","lat":34.72239004,"lng":134.84676967,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、瓦葺、延長54m","structure_material":"煉瓦造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0108","desc":"主屋東北端から敷地北辺に沿って延びる北塀と，主屋西南端から南方に延びる西塀から成り，北塀には石造門の他に潜門２箇所を設ける。主屋の北面及び西面とは連続し，煉瓦二五分分をはね出した段を６条挿入して変化ある外観をつくりだしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002970"},{"id":"00007651","register_sub_id":"101","register_pk":"108633","name":"田近家住宅衣装蔵","kana":"たぢかけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市西昆陽3-350","lat":34.7751306,"lng":135.37876886,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0387","desc":"主屋の東北に蔵前を介して続く。南北棟の切妻造本瓦葺。桁行６．０ｍ梁間４．４ｍ規模の２階建土蔵。外壁は白漆喰仕上げで、一部焼杉板張とする。西面に出入口を設け、２階に窓を開ける。内部は壁板張で、梁に束を建て棟木を支持し、化粧板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007651"},{"id":"00007653","register_sub_id":"101","register_pk":"108635","name":"田近家住宅米蔵","kana":"たぢかけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市西昆陽3-350","lat":34.77518071,"lng":135.37848981,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0389","desc":"敷地西辺、油蔵の南に建つ。桁行９．６ｍ梁間３．９ｍの土蔵造２階建。切妻造本瓦葺の置屋根とする。外壁は切石基礎上、高く竪板を張り、上部漆喰仕上げ。道具蔵及び油蔵と連続して建ち、棟高や竪板の高さ、窓の位置を違え、重厚で変化のある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007653"},{"id":"00007650","register_sub_id":"101","register_pk":"108632","name":"田近家住宅主屋","kana":"たぢかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市西昆陽3-350","lat":34.7751045,"lng":135.37865796,"geo_status":"db","era":"明治20頃／大正4増築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積239㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0386","desc":"敷地中央に南面して建つ。桁行１９ｍ梁間１２ｍと規模が大きい木造つし２階建。屋根桟瓦葺で、西入母屋造東切妻造とし、下屋庇をまわし、正面東寄りから東面に茶室や仏間などを付設し、複雑な屋根を造る。壁は黒漆喰塗。風格ある外観で、庄屋の佇まいを留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007650"},{"id":"00007652","register_sub_id":"101","register_pk":"108634","name":"田近家住宅道具蔵及び油蔵","kana":"たぢかけじゅうたくどうぐぐらおよびあぶらぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市西昆陽3-350","lat":34.77525764,"lng":135.37853575,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階一部平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0388","desc":"敷地の西辺北端から道具蔵及び油蔵が建つ。南北棟の切妻造本瓦葺で、油蔵は棟を低くする。道具蔵は桁行６．９ｍ梁間３．９ｍの２階建土蔵。油蔵は桁行３．９ｍ梁間３．９ｍの平屋建土蔵で、南寄り半間を間仕切る。石積基礎上に高く竪板を張り、上部漆喰仕上げ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007652"},{"id":"00007654","register_sub_id":"101","register_pk":"108636","name":"田近家住宅長屋門","kana":"たぢかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市西昆陽3-350","lat":34.77494356,"lng":135.37865623,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"28 － 0390","desc":"敷地南辺の中央東寄りに建つ。東西棟の切妻造桟瓦葺。桁行１３ｍ梁間４．０ｍ規模の木造平屋建。西寄りに門口を設け、両開戸と潜戸を吊り、東側桁行８．８ｍを部屋とする。外壁は黒漆喰仕上げで、腰に竪板を張る。通り沿いの水路や生垣とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007654"},{"id":"00006612","register_sub_id":"101","register_pk":"107595","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市賀集立川瀬字居屋敷28-1","lat":34.270233,"lng":134.747009,"geo_status":"db","era":"明治14／大正11・昭和初期増築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"28 － 0298","desc":"屋敷地中央に南面して建つ。桁行７間梁間６間、入母屋造本瓦葺のつし２階建。東方を土間、西方を床上部とし、南西の上座敷と北西の居間との間に中廊下を通すのが特徴。西側正面４間分は増築で、仏間や納戸、茶室他を設ける。繊細な造作の数寄屋風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006612"},{"id":"00008313","register_sub_id":"101","register_pk":"133955","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市戸ノ内町3-637","lat":34.74042331,"lng":135.45668046,"geo_status":"db","era":"明治20年頃／明治29年頃・昭和55年・平成5年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0456","desc":"猪名川畔の敷地北半に南面して建ち、建築面積１６５㎡、木造つし２階、入母屋造桟瓦葺である。西半に田の字形を基本として居室を配し、式台を構えた八畳と、座敷飾りを備えた八畳を表側に並べる。外部は上屋を漆喰で塗り込め、風格を備えた大型農家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008313"},{"id":"00008316","register_sub_id":"101","register_pk":"133958","name":"田中家住宅外塀","kana":"たなかけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市戸ノ内町3-637","lat":34.7404907,"lng":135.45679884,"geo_status":"db","era":"明治20年頃／昭和32年・平成20年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"板壁、延長64m","structure_material":"板壁","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0459","desc":"敷地の南側及び北・西面に折れ曲がりに延びる塀で、総延長６４ｍを測る。切石積基礎に建ち、木造、切妻造桟瓦葺で、壁は真壁漆喰塗として、腰高に竪板を張る。土蔵などとともに敷地外周の歴史的景観を形成し、特に東面では東門へのアプローチに趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008316"},{"id":"00008315","register_sub_id":"101","register_pk":"133957","name":"田中家住宅東門","kana":"たなかけじゅうたくとうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市戸ノ内町3-637","lat":34.74033408,"lng":135.45676424,"geo_status":"db","era":"明治20年頃／昭和55年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造、瓦葺、間口3.1m、潜戸付","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0458","desc":"敷地東辺の中ほどに開く正門で、北に外塀が延び、南に離れを接続する。桁行３．１ｍ梁間２．９ｍ、木造平屋建、切妻造桟瓦葺で、門口２．１ｍとして欅一枚板の板戸を両開に吊り、北側の小脇壁に潜り戸を設ける。壁は漆喰塗と竪板張で、外塀と外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008315"},{"id":"00008314","register_sub_id":"101","register_pk":"133956","name":"田中家住宅土蔵","kana":"たなかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市戸ノ内町3-637","lat":34.74047613,"lng":135.45662401,"geo_status":"db","era":"明治20年頃／平成7年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0457","desc":"主屋北西隅に接続して建つ内蔵で、室内側と東面に出入口を開く。桁行５．７ｍ梁間３．６ｍ、土蔵造２階建、切妻造本瓦葺である。基礎は切石積とし、外壁は漆喰塗で、腰高に竪板を張る。東に延びる外塀や西に並ぶ新蔵とともに、歴史的な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008314"},{"id":"00004601","register_sub_id":"101","register_pk":"105591","name":"土田家住宅離れ","kana":"つちだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県高砂市阿弥陀町魚橋1667","lat":34.79212676,"lng":134.79545679,"geo_status":"db","era":"明治37／大正期増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積100㎡","structure_material":"木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"28 － 0189","desc":"旧山陽道側に南面して建つ。東に郵便局舎が連続する。当初は全体がつし２階建で，東側の２階が増築になる。屋根は本瓦葺（一部桟瓦葺）で，外壁及び軒裏を漆喰塗とした重厚な外観になる伝統的民家であるが，ガラス戸を多用した側廻りには近代的要素が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004601"},{"id":"00004602","register_sub_id":"101","register_pk":"105592","name":"土田家住宅門及び塀","kana":"つちだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県高砂市阿弥陀町魚橋1667","lat":34.79207994,"lng":134.79544604,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"門 石造、間口2.0m、塀 木造、延長14m","structure_material":"門 石造","registered":"2005.02.09(平成17.02.09)","register_no":"28 － 0190","desc":"離れの玄関前に門柱２本が２ｍ間隔で立ち，その西に折曲がり延長１３．６ｍの塀が延び，旧山陽道側の敷地境を区画する。門柱は花崗岩製で側面を江戸切仕上げとし，真壁造の塀は腰を縦板張とし，桟瓦葺の屋根を架ける。地域の街路景観をかたちづくる構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004602"},{"id":"00003126","register_sub_id":"101","register_pk":"104116","name":"槌橋家住宅主屋","kana":"つちはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市長田区池田寺町19","lat":34.669098,"lng":135.145386,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0112","desc":"木造２階建，セメント瓦葺で，外壁をスペイン壁風とする洋館。１階には食堂・台所・居間・和室・サンルームを，２階には居室４室を設ける。変化に富んだ窓配置や屋根構成，外壁随所にタイルを用いるなど，大正～昭和期のいわゆる文化住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003126"},{"id":"00012431","register_sub_id":"101","register_pk":"531755","name":"土井家住宅主屋","kana":"どいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大津区平松字屋敷503","lat":34.78973056,"lng":134.5994,"geo_status":"db","era":"明治45年頃／昭和50年代改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積226㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-688","desc":"姫路市郊外の旧平松港で代々多角的に商売を営んだ旧家の住宅。主屋は街路に南面して建ち、正面西半から側面に庭を設ける。入母屋造本瓦葺で、二階正面は開口部として眺望を確保し、両端から側面は漆喰塗で重厚に仕上げる。港町の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012431"},{"id":"00012433","register_sub_id":"101","register_pk":"531757","name":"土井家住宅西土蔵","kana":"どいけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大津区平松字屋敷503","lat":34.78984444,"lng":134.59923889,"geo_status":"db","era":"明治45年頃／昭和50年代改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-690","desc":"主屋の背面、敷地西北隅に南面して建つ。切妻造本瓦葺平入、外壁漆喰塗で正面に庇を付ける。敷地側の腰壁を海鼠壁とし、軒に鉢巻三段を廻し、出入口には観音扉を設けるなど重厚につくる。東土蔵と同じく、伝統的な町家の屋敷構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012433"},{"id":"00012432","register_sub_id":"101","register_pk":"531756","name":"土井家住宅東土蔵","kana":"どいけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市大津区平松字屋敷503","lat":34.78986944,"lng":134.59945833,"geo_status":"db","era":"明治45年頃／昭和50年代改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-689","desc":"主屋の背面、敷地東北隅に南面して建つ。切妻造本瓦葺平入、外壁漆喰塗で、正面中央に庇を出す。西土蔵に比べて規模が小さいが、腰壁や鉢巻、開口部などは同様に重厚につくる。西土蔵と同じく、伝統的な町家の屋敷構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012432"},{"id":"00000990","register_sub_id":"101","register_pk":"101980","name":"冨永家住宅主屋","kana":"とみながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区深江南町1-3-9","lat":34.72089028,"lng":135.30073554,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造２階建，瓦葺，建築面積93㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0030","desc":"大正末期に開発された通称芦屋文化村と呼ばれる小住宅地に建つ洋風住宅。木材関係の仕事をしていた施主の冨永初造の構想案をもとに馴染みの建築家ベイリーが設計し，大工吉田勝二郎が施工した。枠組工法の原型をなす作品で，近代住宅史上も貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000990"},{"id":"00000991","register_sub_id":"101","register_pk":"101981","name":"冨永家住宅附属屋","kana":"とみながけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区深江南町1-3-9","lat":34.72080933,"lng":135.30074318,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建，瓦葺，建築面積11㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0031","desc":"敷地の南側に位置し，端正な意匠になる総２階建の主屋と同様，窓枠を白色，外壁を緑色に塗って，簡潔にまとめあげる。切妻造，平屋建の小規模な建物で，背後に庇が付き，道路側に大きく開いた方形の窓を見せる。主屋と共に，大正期の洋風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000991"},{"id":"00008538","register_sub_id":"101","register_pk":"134934","name":"永田家住宅池石積","kana":"ながたけじゅうたくいけいしづみ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32631029,"lng":134.79509822,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、延長32ｍ","structure_material":"石造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0485","desc":"離れ南側に築かれた池の石積で、矩形の池の西面と南面を張り出してＬ字形をなし、東西五・九メートル南北九・八メートル、深さ二・七メートルを測る。砂岩切石を、弛みをもたせて巧緻に積み、一部に瓢箪と杯をかたどった積石も用いて風情をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008538"},{"id":"00008539","register_sub_id":"101","register_pk":"134935","name":"永田家住宅家具蔵","kana":"ながたけじゅうたくかぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32649055,"lng":134.79496302,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0486","desc":"離れ後方に渡り廊下を介して建つ。桁行七・二メートル梁間四・六メートル、土蔵造二階建、東切妻造、西入母屋造、本瓦葺で、東・南面に庇を付け、二階に和室二室を配する。外壁は一階を竪板張、二階は土壁の上に鉄板を貼る。往時の生活様式を伝える蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008539"},{"id":"00008536","register_sub_id":"101","register_pk":"134932","name":"永田家住宅主屋","kana":"ながたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32650632,"lng":134.79521089,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積313㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0483","desc":"敷地中央に南面する。桁行一九メートル梁間一二メートル、木造二階建、入母屋造本瓦葺で、四周を下屋とし便所と物置を付属。平面は東側がもと土間、西の床上部は二列六室を基本とし、表三室を座敷とする。当地方の近世民家形式を伝える大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008536"},{"id":"00008544","register_sub_id":"101","register_pk":"134940","name":"永田家住宅高塀","kana":"ながたけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32638124,"lng":134.79487771,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長27m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0491","desc":"敷地の北・東辺に矩折れに延びる。折れ曲がり延長二七メートル、高さ四・三メートル、両下造桟瓦葺で、切石積基礎に土台を伏せ、方柱をたて、腕木で軒桁を受ける。柱間は雨戸をたて、夏季には開放して北から川風を取入れる工夫がされた、独特な形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008544"},{"id":"00008542","register_sub_id":"101","register_pk":"134938","name":"永田家住宅通用門","kana":"ながたけじゅうたくつうようもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32659195,"lng":134.79532581,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積8.4㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0489","desc":"主屋東側に接続して建ち、門と物置からなる。桁行五・三メートル梁間一・八メートル、木造平屋建、切妻造本瓦葺である。西側の門は潜り付の板戸を両開とし、蹴放しの布石には荷車用の欠き取りが残る。前庭と内庭を画する通用門で、屋敷構えを特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008542"},{"id":"00008540","register_sub_id":"101","register_pk":"134936","name":"永田家住宅土蔵","kana":"ながたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32667532,"lng":134.79520413,"geo_status":"db","era":"大正後期／昭和50年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0487","desc":"敷地東面後方に東西棟で建ち、桁行一一メートル梁間四・九メートル、土蔵造、東面切妻造、西面入母屋造、本瓦葺で、南面に庇を付ける。正面二ヶ所を出入口とし、外壁は腰高に竪板を張り、正・背面に高窓を穿つ。旧家の屋敷構えを構成する大型土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008540"},{"id":"00008541","register_sub_id":"101","register_pk":"134937","name":"永田家住宅長屋門","kana":"ながたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32639366,"lng":134.79540467,"geo_status":"db","era":"明治37年","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0488","desc":"主屋正面に建ち、桁行一七メートル梁間五・九メートルと大型の長屋門。木造平屋建、入母屋造本瓦葺で、周囲に庇を付ける。中央に門を開き、東側を物置、西側を居室につくる。外壁は腰高に竪板を張り、格子窓を穿つ。風格のある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008541"},{"id":"00008537","register_sub_id":"101","register_pk":"134933","name":"永田家住宅離れ座敷","kana":"ながたけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32638239,"lng":134.79499457,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0484","desc":"主屋西側に便所を介して建ち、桁行九・八メートル梁間八・〇メートル、平屋建、寄棟造本瓦葺である。八畳二室の南北に畳縁を配し、四周に濡縁をまわす。西側の主室はトコと棚を備え、正面濡縁は池に張り出して洋風の手摺を付ける。開放的なつくりの接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008537"},{"id":"00008543","register_sub_id":"101","register_pk":"134939","name":"永田家住宅棟門及び塀","kana":"ながたけじゅうたくむなもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県南あわじ市倭文長田字吉野坊1493","lat":34.32643197,"lng":134.79526722,"geo_status":"db","era":"明治中期／平成12年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、瓦葺、間口2.0m 塀 土塀、瓦葺、延長23m","structure_material":"門 木造","registered":"2011.01.26(平成23.01.26)","register_no":"28 － 0490","desc":"主屋正面に構えた棟門と、池の入口まで矩折れに延びる塀からなる。棟門は、一間棟門、切妻造本瓦葺で、本柱を頭貫と台輪で固め、頭貫や腕木に絵様を刻み、中備に皿斗付大斗を置き、社寺風につくる。桟瓦葺築地塀の塀とともに、上質な庭空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008543"},{"id":"00004274","register_sub_id":"101","register_pk":"105264","name":"西尾家住宅主屋","kana":"にしおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.097012,"lng":135.138199,"geo_status":"db","era":"享保18","year":1733,"year_source":"db","year_min":1733,"year_max":1733,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積332㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0176","desc":"旧山陰道に北面する敷地の北寄りに建つ。主体部は南北棟の片入母屋造，桟瓦葺で，平面規模は桁行８間梁行６間半，北面に下屋庇を廻して玄関をとる。東側を土間，西側を床上部とし，西南に座敷と茶室を張り出し，北西の１０畳座敷部は東西棟の角屋状につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004274"},{"id":"00004277","register_sub_id":"101","register_pk":"105267","name":"西尾家住宅新蔵一","kana":"にしおけじゅうたくしんぐらいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09698877,"lng":135.1379713,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0179","desc":"中蔵の南方に南北棟で建つ。桁行４間梁間２間規模，切妻造，桟瓦葺の２階建土蔵で，基礎を花崗石積とし，東面に土庇を差し掛けて１戸口を開ける。屋根は置屋根式で，外部は腰を焼杉の縦板張，上部を漆喰塗として南妻面に整った外観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004277"},{"id":"00004275","register_sub_id":"101","register_pk":"105265","name":"西尾家住宅茶室","kana":"にしおけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09714087,"lng":135.13808535,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板及び瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0177","desc":"主屋座敷の西方に東西棟，銅板葺で建ち，座敷裏の縁から渡り縁で繋がる。３畳水屋と６畳茶室から成り，西面北寄りに床を設け，南寄りに風呂先窓を開ける。内部に鴨居を渡し４畳半茶室として使えるようにしている。主屋座敷との間に便所と風呂を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004275"},{"id":"00004281","register_sub_id":"101","register_pk":"105271","name":"西尾家住宅離れ","kana":"にしおけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09708717,"lng":135.138397,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積50㎡、通用門及び塀付","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0183","desc":"屋敷地の北東隅部に位置し，旧山陰道に沿って東西棟で建つ。桁行５間半梁間２間半規模，切妻造，桟瓦葺の平屋建で，南面に下屋を設ける。西側桁行１間半分は落棟とし，西面の南端と主屋北東端との間には通用門を開く。玄関前庭を構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004281"},{"id":"00004276","register_sub_id":"101","register_pk":"105266","name":"西尾家住宅部屋蔵・中蔵","kana":"にしおけじゅうたくへやぐら・なかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09708149,"lng":135.13801746,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0178","desc":"主屋の西方，茶室の南方に南北棟で建つ。桁行５間梁間２間規模，切妻造，桟瓦葺の２階建土蔵で，東面に土庇を差し掛けて２戸口を設ける。内部は２室に分けるが，構造的には別々の蔵で，北寄りを道具蔵とし，置屋根形式のひとつ屋根を一体的に架けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004276"},{"id":"00004282","register_sub_id":"101","register_pk":"105272","name":"西尾家住宅前庭門及び塀","kana":"にしおけじゅうたくまえにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09719193,"lng":135.13814755,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口4.8m、塀延長20m","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0184","desc":"主屋座敷と続きの間との室境北端に発し，旧山陰道に沿って屋敷地北辺を画し，茶室北西端に取り付く折曲がり延長１４間の外塀。北面側は腰縦板張，真壁造の桟瓦葺で，東面側は銅板葺とし前庭門を開く。玄関前から街道沿いの正面景観に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004282"},{"id":"00006170","register_sub_id":"101","register_pk":"107154","name":"西山酒造場離れ","kana":"にしやましゅぞうじょうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波市市島町中竹田1171他","lat":35.240952,"lng":135.129562,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積126㎡","structure_material":"木造平屋一部2階建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0271","desc":"敷地中央，小路から引き込んだ露地沿いに建つ。木造平屋一部二階建，入母屋造，桟瓦葺。西側は屋根を長く張り出し，東側は土蔵風の主体部に洋風ガラス戸を開いたテラスを張り出し，変化を与える。内部も座敷飾付の和室と洋室を併せ持ち，折衷型住宅とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006170"},{"id":"00015336","register_sub_id":"101","register_pk":"532460","name":"萩野家住宅座敷棟","kana":"はぎのけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市須磨区潮見台町一丁目28","lat":34.64451389,"lng":135.11019167,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0828","desc":"洋館の北東に位置する座敷棟。入母屋造桟瓦葺の南北棟で、南東に便所棟を延ばし、南庭を囲う。内部は二室の続き間座敷で、南室に床・琵琶床・違棚・付書院を備え、縁を介して南庭を望む。床柱に絞丸太や瘤付丸太を用いた瀟洒なつくりで、良材吟味した座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015336"},{"id":"00015337","register_sub_id":"101","register_pk":"532461","name":"萩野家住宅土蔵","kana":"はぎのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市須磨区潮見台町一丁目28","lat":34.64469167,"lng":135.11006389,"geo_status":"db","era":"大正前期／平成7年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、鉄板葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0829","desc":"敷地北西隅に建つ家財蔵。切石積基礎に南面して建つ２階建切妻造妻入鉄板葺で、外壁は漆喰塗仕上。内部は各階１室の板敷で南西に階段を設け、２階上部に登梁と束立の和小屋を現す。正面戸口の楣上に精緻な鏝絵で波と龍を飾るなど、高い左官技術を用いた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015337"},{"id":"00015335","register_sub_id":"101","register_pk":"532459","name":"萩野家住宅洋館","kana":"はぎのけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市須磨区潮見台町一丁目28","lat":34.64443333,"lng":135.11007222,"geo_status":"db","era":"明治40年頃／平成7年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0827","desc":"須磨海岸北側の高台に位置する郊外住宅の洋館。敷地南西に南面して建つ、２階建寄棟造妻入で、外壁下見板張。柱を並べた開放的な玄関ポーチとベランダを正面に構え、各階二室で側面に縦長窓を配する。菱組天井のベランダから眺望優れたコロニアル様式の洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015335"},{"id":"00001445","register_sub_id":"101","register_pk":"102435","name":"白鶴美術館茶室（崧庵）","kana":"はくつるびじゅつかんちゃしつ（すうあん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73070496,"lng":135.25824952,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺一部瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0060","desc":"六甲の地に所在した茶室建築を昭和３１年に当地に移築したもの。事務棟の北西，本館と事務棟との間の中庭を望む位置に建つ。茶室部は入母屋屋根の中央を瓦葺とし，その周囲に銅板を葺回した瀟洒な外観を呈し，かつ上質な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001445"},{"id":"00009808","register_sub_id":"101","register_pk":"195637","name":"花井家住宅主屋","kana":"はないけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県高砂市高砂町字高瀬町1511","lat":34.74738621,"lng":134.80556529,"geo_status":"db","era":"明治後期／平成23改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積138㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0566","desc":"南東角地に東西棟で建つつし二階の町家で、入母屋造の東妻に小屋根を重ね、南東面に下屋を廻らす。南正面に出格子を設け、上階は漆喰で塗り込め、格子窓を並べる。内部は東寄りを通り土間とし、西側に居室を三室ずつ二列配する。比較的間口の広い近代の商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009808"},{"id":"00012778","register_sub_id":"101","register_pk":"367681","name":"東多田夢勝庵裏門及び北塀","kana":"ひがしただむしょうあんうらもんおよびきたへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"裏門 木造、瓦葺、間口2.0m 北塀 土塀、瓦葺、総延長18m","structure_material":"裏門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 713","desc":"北塀は敷地東北隅を区切る、基礎乱石積、外壁漆喰塗、屋根桟瓦葺の築地塀。敷地東面の北端から緩やかに向きを変えて敷地北面の中ほどまで延び、途中に薬医門形式、切妻造桟瓦葺の裏門を設ける。敷地背面の道路に面し、屋敷後方の構えを重厚に整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012778"},{"id":"00012774","register_sub_id":"101","register_pk":"367677","name":"東多田夢勝庵主屋","kana":"ひがしただむしょうあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"江戸後期／昭和10年頃・同44年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 709","desc":"猪名川東側にある集落の旧庄屋宅。主屋は敷地後方に南面して建つ。入母屋造桟瓦葺の平屋建で軒を出桁造とし、四周に廻した下屋上を塗込めて虫籠窓を穿つ。東に土間、西の前後に各3室を配し、前列上手に座敷を設ける。伝統的な集落景観の核をなす大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012774"},{"id":"00012775","register_sub_id":"101","register_pk":"367678","name":"東多田夢勝庵土蔵","kana":"ひがしただむしょうあんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積22㎡、土塀付","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 710","desc":"敷地西北隅に建つ家財蔵。土蔵造二階建、切妻造桟瓦葺で東面南寄りに扉口を設ける。外壁は漆喰塗の腰縦板張で、屋根を置屋根状につくり、軒裏まで塗込める。内部は上下階とも板敷で、小屋組は母屋桁上に直接板を張る。屋敷後方の構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012775"},{"id":"00012777","register_sub_id":"101","register_pk":"367680","name":"東多田夢勝庵長屋門","kana":"ひがしただむしょうあんながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"文久3年（1863）／昭和10年・同55年頃改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 712","desc":"敷地東南隅に建つ。Ｌ字形平面の平屋建、西面入母屋造、北面切妻造の桟瓦葺で、外壁は真壁造漆喰塗の腰縦板張である。折曲り延長40メートル、東面と南面のほぼ中央に門口を開き、両開き板扉を構え、潜戸を備える。旧家の堂々たる表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012777"},{"id":"00012779","register_sub_id":"101","register_pk":"367682","name":"東多田夢勝庵西塀","kana":"ひがしただむしょうあんにしへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長14m","structure_material":"土塀","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 714","desc":"敷地西面を区切る築地塀。敷地西面南端から中ほどまで延びる。基礎は自然石積、屋根は桟瓦葺、外側は漆喰塗で重厚に仕上げるが、庭に面する内側は粗めの中塗で仕上げ、内外で表情を異にする。旧家の屋敷構えを構成するとともに庭の添景の役割も果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012779"},{"id":"00012776","register_sub_id":"101","register_pk":"367679","name":"東多田夢勝庵露地門及び庭塀","kana":"ひがしただむしょうあんろじもんおよびにわへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市東多田二丁目647-1","lat":34.85591778,"lng":135.41996694,"geo_status":"db","era":"江戸後期／明治前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"露地門 木造、杉皮葺、間口1.0m 庭塀 土塀、瓦葺、総延長16m","structure_material":"露地門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 711","desc":"庭塀は敷地前方を東西に区切る、外壁漆喰塗、屋根桟瓦葺の築地塀。長屋門背面の西端から北に延び、主屋手前で東に折れて露地門を開き、北に折れて主屋正面の中央部に接続する。露地門は棟門形式の切妻造杉皮葺である。主屋正面の構えを格調高く整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012776"},{"id":"00007772","register_sub_id":"101","register_pk":"108753","name":"姫路文学館望景亭（旧濱本家住宅）石垣","kana":"ひめじぶんがくかんぼうけいてい（きゅうはまもとけじゅうたく）いしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市山野井町字宮根86他","lat":34.84156092,"lng":134.68759956,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造一部煉瓦造、総延長64m","structure_material":"石造一部煉瓦造","registered":"2009.08.07(平成21.08.07)","register_no":"28-0398","desc":"庭園南辺から西辺にかけて延びる石垣で、和室に接続する。折曲り延長６４ｍ、最大高さ１．５ｍ、石造一部煉瓦造で、上部に生垣を植える。石積部分は大振りの自然石を乱積とし、西辺に間口１．２ｍの開口をもつ。広場と和室前庭をつなぐ重厚な趣の石垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007772"},{"id":"00007769","register_sub_id":"101","register_pk":"108750","name":"姫路文学館望景亭（旧濱本家住宅）茶室","kana":"ひめじぶんがくかんぼうけいてい（きゅうはまもとけじゅうたく）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市山野井町字宮根86他","lat":34.84174963,"lng":134.68770423,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0395","desc":"和室と池を挟んで建つ茶室。桁行８．１ｍ梁間６．９ｍ、木造平屋建。切妻造桟瓦葺で、下屋をめぐらして外観を和室と調和させる。八畳の茶室と水屋からなり、庭側の開口を広くとる。トコ脇前を舟底天井とするなど凝ったつくりになる、開放的な茶室建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007769"},{"id":"00007771","register_sub_id":"101","register_pk":"108752","name":"姫路文学館望景亭（旧濱本家住宅）棟門","kana":"ひめじぶんがくかんぼうけいてい（きゅうはまもとけじゅうたく）むねもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市山野井町字宮根86他","lat":34.84170835,"lng":134.68790621,"geo_status":"db","era":"昭和前期／平成3移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、銅板葺、間口1.5m","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"28-0397","desc":"望景亭敷地の東端、文学館本館からの導入路に東面して建つ。間口１．５ｍの腕木門、切妻造銅板葺で、控柱を建てる。一軒疎垂木。上部に菱格子を嵌める両開桟唐戸を吊り、女梁に絵様を施し、屋根は出の深い起り屋根とする。端正で洗練された意匠の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007771"},{"id":"00007770","register_sub_id":"101","register_pk":"108751","name":"姫路文学館望景亭（旧濱本家住宅）廊下","kana":"ひめじぶんがくかんぼうけいてい（きゅうはまもとけじゅうたく）ろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市山野井町字宮根86他","lat":34.84178575,"lng":134.68762388,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0396","desc":"和室と茶室を矩折れに繋ぐ廊下で、延長９．６ｍの木造平屋建、招屋根桟瓦葺である。自然石を乱積風に見せる基礎上に建ち、外壁は土壁で腰モルタル洗い出し。廊下の南北にある庭を往来するための通路を跨ぐために足下をアーチ状につくる、特徴的な外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007770"},{"id":"00007768","register_sub_id":"101","register_pk":"108749","name":"姫路文学館望景亭（旧濱本家住宅）和室","kana":"ひめじぶんがくかんぼうけいてい（きゅうはまもとけじゅうたく）わしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市山野井町字宮根86他","lat":34.84171278,"lng":134.68752658,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積177㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0394","desc":"敷地の西奥に位置する。桁行１４ｍ梁間１１ｍ、木造平屋建、入母屋造桟瓦葺である。高い基礎上に建ち、内部は十八畳の座敷に十二畳の次の間を並べ、高欄付の縁をめぐらす。庭の眺望を意識した開放的なつくりで、欄間などの造作も洗練された、瀟洒な書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007768"},{"id":"00013856","register_sub_id":"101","register_pk":"507815","name":"廣田家住宅主屋","kana":"ひろたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.74982778,"lng":135.42803889,"geo_status":"db","era":"明治41年／昭和51年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積240㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0759","desc":"尼崎市北部の住宅街に位置する大型民家。桁行九間梁間六間、入母屋造平入茅葺（銅板仮葺）。四周に桟瓦葺の下屋を付し、東に付属屋を配する。内部は東は土間、西の床上部は整形六間取とし南面中央に式台を構える。代々庄屋を務めた旧家の明治期の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013856"},{"id":"00013857","register_sub_id":"101","register_pk":"507816","name":"廣田家住宅北離れ","kana":"ひろたけじゅうたくきたはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.7499,"lng":135.42804167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0760","desc":"主屋の北、敷地北辺の土蔵の東に接して建つ。平屋建で規模は桁行二間半梁間一間半、屋根は切妻造桟瓦葺とし、外壁は腰を竪板張、上部を白モルタル塗とする。内部は四畳半の座敷一室で西に半間の床を構える。土蔵とともに敷地北辺の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013857"},{"id":"00013858","register_sub_id":"101","register_pk":"507817","name":"廣田家住宅土蔵","kana":"ひろたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.74991389,"lng":135.42798333,"geo_status":"db","era":"弘化5年(1848)","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0761","desc":"主屋の北、敷地北辺に接して建つ。桁行三間梁間二間、土蔵造二階建切妻造本瓦葺で東西棟とし、南面東寄りを戸口とする。外壁は漆喰塗で鉢巻まで塗込め、腰は竪板張。内部は一、二階とも一室。幕末に遡る敷地内最古の建物で、上層農家の屋敷景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013858"},{"id":"00013859","register_sub_id":"101","register_pk":"507818","name":"廣田家住宅長屋門","kana":"ひろたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.7496,"lng":135.42805833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0762","desc":"敷地南辺の通りに面して建つ。桁行三間半梁間二間半で屋根は切妻造桟瓦葺とし、西半に門口、東半に物置を配する。門口は板戸両開きとし、東袖に潜戸を設ける。壁は正面を腰竪板張、上部黒漆喰塗とし、背面は白漆喰に塗分ける。旧家の格式ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013859"},{"id":"00013861","register_sub_id":"101","register_pk":"507820","name":"廣田家住宅庭門及び塀","kana":"ひろたけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.74972222,"lng":135.42790833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"庭門 木造、瓦葺、間口1.2m、塀 木造、瓦葺、総延長16m","structure_material":"庭門 木造","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0764","desc":"主屋式台の西柱から奥座敷前の庭を囲み矩折に延びる門及び塀。庭門は腕木門で屋根は切妻造桟瓦葺とし、菱格子付の引込板戸を建てる。塀の壁は外面は腰を竪板張、上部を白モルタル塗とし、内面は上部を白、腰を灰色のモルタルで塗分け、庭内外の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013861"},{"id":"00013860","register_sub_id":"101","register_pk":"507819","name":"廣田家住宅南塀","kana":"ひろたけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市上坂部二丁目162","lat":34.7496,"lng":135.42793056,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、瓦葺、延長20m","structure_material":"煉瓦造","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0763","desc":"敷地と南面街路を区画する塀で、東端は長屋門に接し、西端は北にやや屈曲する。高さ二メートル、総延長一九メートルの煉瓦造桟瓦葺で、敷地外面を鼠色、内面を白色のモルタル塗として長屋門との調和を図る。長屋門とともに通りに面した旧家の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013860"},{"id":"00003577","register_sub_id":"101","register_pk":"104567","name":"鳳鳴酒造土蔵一","kana":"ほうめいしゅぞうどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町48","lat":35.07671786,"lng":135.22020952,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0129","desc":"敷地の北西隅に建ち，主屋，事務室一と連続して立面を形成している。土蔵造平屋建，切妻造，桟瓦葺で，軒まで漆喰塗込とする。扉口を東側に開き，南面に窓を設けるのみで，街路側は上部漆喰壁，腰の高い位置まで板張りとする。街路景観を構成する土蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003577"},{"id":"00003579","register_sub_id":"101","register_pk":"104569","name":"鳳鳴酒造土蔵二","kana":"ほうめいしゅぞうどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町46","lat":35.07650162,"lng":135.22038776,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0131","desc":"主屋の背面側，敷地東側に建つ。南北棟，切妻造，桟瓦葺，建築面積２３㎡の土蔵造２階建で，置屋根形式とし、置屋根の母屋桁等を塗り籠める。腰は海鼠壁とし，北面西よりに両開の扉を設け，上部に小窓を開く。立ちの高い立面が特徴で，土蔵建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003579"},{"id":"00003578","register_sub_id":"101","register_pk":"104568","name":"鳳鳴酒造離れ","kana":"ほうめいしゅぞうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県篠山市呉服町48","lat":35.07663786,"lng":135.22021976,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0130","desc":"土蔵一の背面側，敷地西側に建ち，東側で主屋と接続する。内部は和室３室と洋室１室を設け，北側東寄りには式台玄関を設け，南面には縁を通して東端に便所を突出して設ける。南西寄りの１０畳間に床を備え，北面には欄間飾りを備えるなど意匠を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003578"},{"id":"00016701","register_sub_id":"101","register_pk":"579185","name":"細田家住宅アクタンヤ","kana":"ほそだけじゅうたくあくたんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093658,"lng":134.891786,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積19㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0885","desc":"敷地北東部に位置する灰や炭などの保管庫。二階建切妻造平入桟瓦葺で東隣の納屋と一連で屋根を葺く。外壁は大壁漆喰塗仕上。各階板敷の一室で、二階西面に窓を開け、小屋は束立で棟木を受ける。往時の生活の様相を伝え、小規模ながら敷地北東の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016701"},{"id":"00016691","register_sub_id":"101","register_pk":"579175","name":"細田家住宅主屋","kana":"ほそだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093608,"lng":134.891576,"geo_status":"db","era":"江戸後期／明治中期改修、昭和前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺(鉄板仮葺)及び瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0875","desc":"杉原川右岸の集落中心部に位置する旧家の主屋。敷地中央に建つ切妻造東西棟茅葺(鉄板仮葺)で、北に棟を延ばし、東に落棟を付し、複雑に屋根をかける。座敷は西に床、北に棚を配した変則的な構えとする。正面の棟上に切妻破風をみせ、地域景観の核となる主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016691"},{"id":"00016700","register_sub_id":"101","register_pk":"579184","name":"細田家住宅北門","kana":"ほそだけじゅうたくきたもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093672,"lng":134.891751,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0884","desc":"敷地北面の東寄りに開く通用門。切妻造平入桟瓦葺で北面中央に両開の板扉を吊り、両脇間の壁は漆喰塗で、腰は竪板を高く張る。内部は土間とし、東・西の妻壁を設けず、上部に和屋組を現す。全体に簡素ながらも間口が大きく、敷地北面の景観を形成する北門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016700"},{"id":"00016699","register_sub_id":"101","register_pk":"579183","name":"細田家住宅木屋","kana":"ほそだけじゅうたくきや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093693,"lng":134.891708,"geo_status":"db","era":"江戸末期／昭和中期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0883","desc":"敷地北面東寄りに位置する木屋。二階建で西隣の味噌蔵と一連で屋根を葺き、東側は寄棟とする。外壁は大壁の漆喰塗仕上、北面の腰は高く竪板を張る。小屋は登梁と束立を併用し、母屋や地棟に丸太を用いる。西側の土蔵群に連なり、敷地北面に重厚な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016699"},{"id":"00016692","register_sub_id":"101","register_pk":"579176","name":"細田家住宅化粧部屋","kana":"ほそだけじゅうたくけしょうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093612,"lng":134.89144,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0876","desc":"主屋と座敷棟の間に位置し、かつて厠であったと伝わる化粧部屋。平屋建入母屋造桟瓦葺の南北棟で北・南・東に縁を廻す。内部は一室の板間で棹縁天井とし、北面はガラス窓、南面はガラス戸とした開放的なつくり。主屋や座敷棟と並び敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016692"},{"id":"00016693","register_sub_id":"101","register_pk":"579177","name":"細田家住宅座敷棟","kana":"ほそだけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093632,"lng":134.891381,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0877","desc":"主屋の東方に、化粧部屋を介して接続する座敷棟。平屋建入母屋造桟瓦葺の南北棟で、内部は３室を並べ、南・北・東面に縁を廻す。８畳の南室は床と床脇に天袋、付書院を備えた端正な座敷で、６畳の北室は数寄屋風で細部に意匠を凝らす。上質なつくりの座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016693"},{"id":"00016694","register_sub_id":"101","register_pk":"579178","name":"細田家住宅新蔵","kana":"ほそだけじゅうたくしんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093722,"lng":134.891368,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0878","desc":"敷地の北西隅に位置する家財蔵。土蔵造二階建切妻造平入、置屋根形式の桟瓦葺とする。外壁は大壁の漆喰塗で南面に１箇所窓を開ける。平面は敷地に合わせた台形とし、内部は各階一室の板敷で、小屋は太い地棟に登梁を架ける。窓が小さく閉鎖的な構えの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016694"},{"id":"00016696","register_sub_id":"101","register_pk":"579180","name":"細田家住宅中蔵","kana":"ほそだけじゅうたくなかくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093722,"lng":134.891489,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0880","desc":"敷地北面西寄りに位置する家財蔵。土蔵造二階建切妻造平入、置屋根形式の桟瓦葺で南面に下屋を付し、東寄りに戸口に開ける。各階一室の板敷で、小屋は桁行中央に架けた梁上の束で母屋と棟木を支え、野地板を流板に張る。西蔵に連なり、敷地北面の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016696"},{"id":"00016702","register_sub_id":"101","register_pk":"579186","name":"細田家住宅納屋","kana":"ほそだけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093602,"lng":134.891798,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造二階建、瓦葺、建築面積68㎡","structure_material":"木造二階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0886","desc":"敷地北東隅に位置する納屋。二階建南北棟の桟瓦葺で南は入母屋造、北はアクタンヤと一連の屋根とする。外壁は大壁漆喰塗仕上で軒を現し、北・西面の腰は高い竪板張。内部は三室の土間で二階は物置、小屋は登梁と束立を交互に組む。敷地東辺を画す長大な納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016702"},{"id":"00016695","register_sub_id":"101","register_pk":"579179","name":"細田家住宅西蔵","kana":"ほそだけじゅうたくにしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093734,"lng":134.891422,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0879","desc":"敷地北西部、新蔵の東隣に建つ家財蔵。土蔵造二階建切妻造平入、置屋根形式の桟瓦葺で南面に下屋を付し、東寄りに戸口に開ける。各階一室の板敷で、一階は北面に押入を設け、小屋は曲梁に束立とし、野地板を流板に張る。敷地北面の重厚な景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016695"},{"id":"00016703","register_sub_id":"101","register_pk":"579187","name":"細田家住宅風呂及び便所","kana":"ほそだけじゅうたくふろおよびべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093474,"lng":134.891496,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0887","desc":"座敷棟の南に位置する賓客用の風呂及び便所。入母屋造桟瓦葺の南北棟で内部は北から脱衣場、風呂場、大便所、小便所、手洗場を並べ、西面に濡縁を付す。脱衣場は東面に床と床脇に天袋と違棚を構え、風呂場は天井の棹を放射状に配るなど凝ったつくりの付属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016703"},{"id":"00016698","register_sub_id":"101","register_pk":"579182","name":"細田家住宅味噌蔵","kana":"ほそだけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093701,"lng":134.891632,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0882","desc":"敷地北面東寄りに位置する味噌蔵。土蔵造二階建、切妻造平入桟瓦葺で、東隣の物置、西の木屋と一連で屋根を葺く。外壁は大壁漆喰塗仕上、北面腰は高く竪板を張る。小屋は登梁と束立を併用とし、母屋や棟木に丸太を用いる。窓を設けず、閉鎖的な構えの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016698"},{"id":"00016697","register_sub_id":"101","register_pk":"579181","name":"細田家住宅物置","kana":"ほそだけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県多可郡多可町加美区熊野部字杉之本423-1","lat":35.093712,"lng":134.891574,"geo_status":"db","era":"昭和前期／昭和中期増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積14㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0881","desc":"敷地北面中央部に位置する物置。二階建切妻造平入桟瓦葺で東隣の味噌蔵と一連で屋根を葺く。外壁は大壁漆喰塗で北面の腰は高く竪板を張る。各階一室で東・西の内壁は両隣の土蔵と共有し、母屋や棟木に丸太を用いる。小規模ながら敷地北面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016697"},{"id":"00008013","register_sub_id":"101","register_pk":"128844","name":"本田家住宅乾蔵","kana":"ほんだけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市西本町2-91","lat":34.71389658,"lng":135.41444266,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"28-0443","desc":"主屋の西隣に建つ。桁行５．９ｍ梁間４．０ｍの土蔵造２階建、切妻造桟瓦葺。外壁に竪板を高く張り、東面に出入口を開き、２階北面の窓には、猿頬庇や持送りの意匠を凝らして漆喰で仕上げる。平入の主屋と対照的に妻壁を見せ、変化のある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008013"},{"id":"00008012","register_sub_id":"101","register_pk":"128843","name":"本田家住宅主屋","kana":"ほんだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市西本町2-91","lat":34.7138605,"lng":135.41456622,"geo_status":"db","era":"江戸末期／昭和前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"28-0442","desc":"北側道路に面して建ち、桁行１１ｍ梁間１２ｍ、木造つし２階建、切妻造桟瓦葺で、西南角の座敷を西に突き出す。正面は黒漆喰塗で、出格子を付け腰を竪板張とし、虫籠窓を穿つ。軒を出桁造で深め、屋根をやや起らせ建ちも低く、落ち着いた外観の町家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008012"},{"id":"00008014","register_sub_id":"101","register_pk":"128845","name":"本田家住宅巽蔵","kana":"ほんだけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市西本町2-91","lat":34.7137762,"lng":135.41453295,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"28-0444","desc":"主屋の南側に建つ内蔵で、西側を出入口として主屋と縁で接続する。桁行４．８ｍ梁間４．１ｍの土蔵造２階建、東西棟の切妻造妻入桟瓦葺で、外壁は漆喰仕上げで水切りを二段付ける。２階は裏通りに面する南側に窓を穿つ。商家裏手の屋敷景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008014"},{"id":"00002563","register_sub_id":"101","register_pk":"103553","name":"舞子公園旧木下家住宅主屋","kana":"まいここうえんきゅうきのしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市垂水区東舞子町","lat":34.633224,"lng":135.036575,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積275㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"28 － 0073","desc":"県立舞子公園の東端，山陽電鉄の南方に位置する。民家風の虫籠窓を付けた東西棟の大棟を中心に，東面に玄関，北東に台所，西北に茶室，南東に応接室，南西に仏間を配したＨ字型平面をもつ。昭和初期における阪神間の数寄屋造による和風邸宅の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002563"},{"id":"00002564","register_sub_id":"101","register_pk":"103554","name":"舞子公園旧木下家住宅土蔵","kana":"まいここうえんきゅうきのしたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市垂水区東舞子町","lat":34.63339459,"lng":135.03648773,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"28 － 0074","desc":"主屋北西端に位置する茶室の北方に建つ。南北棟，切妻造，本瓦葺の妻入，２階建土蔵で，桁行３間，梁間２間規模を有する。外観は白漆喰塗とし，南妻面に庇を付けて戸前とするほか，２階の東面と南面に窓を設ける。窓庇の持送りに丁寧な仕事振りがうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002564"},{"id":"00002565","register_sub_id":"101","register_pk":"103555","name":"舞子公園旧木下家住宅納屋","kana":"まいここうえんきゅうきのしたけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市垂水区東舞子町","lat":34.63344372,"lng":135.03647678,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"28 － 0075","desc":"山陽電鉄線路寄りで土蔵の北方に建つ。東西棟，切妻造，桟瓦葺の２階建建家で，桁行３間，梁間２間規模を有し，南面全面にわたって１間幅の２階建ベランダを添わす。階下は１室であるが，階上は４畳と４畳半規模の２室とする。邸宅の主要構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002565"},{"id":"00002071","register_sub_id":"101","register_pk":"103061","name":"前田家住宅主屋","kana":"まえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県三田市屋敷町12-3","lat":34.88454572,"lng":135.22199683,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"28 － 0071","desc":"木造２階建，桟瓦葺，外壁はもとモルタル砂利洗出し仕上げ。南側壁面に半円アーチ窓をならべ，北東隅の２階床を持送とし，屋根に赤瓦を葺くなど，スパニッシュ風の外観を示す。阪神間では昭和初期にスパニッシュスタイルが流行するが，その早い事例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002071"},{"id":"00009191","register_sub_id":"101","register_pk":"164744","name":"増田家住宅（旧モロゾフ家住宅）石垣及び塀","kana":"ますだけじゅうたく（きゅうもろぞふけじゅうたく）いしがきおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区北野町4-85-1他","lat":34.69967288,"lng":135.18697763,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"石垣 石造、延長53m 塀 コンクリート造、瓦葺、延長53m","structure_material":"石垣 石造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の南面と西面に築かれ、延長53メートルを測る。間知石谷積の石垣上にコンクリート造の塀を築き、上部に丸瓦を伏せる。南西方からの道路の分岐となる隅部は、優美な鋭角の曲面を描く。白色の塀と茶色の丸瓦が主屋の外観と調和し、北野地区の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009191"},{"id":"00009190","register_sub_id":"101","register_pk":"164743","name":"増田家住宅（旧モロゾフ家住宅）主屋","kana":"ますだけじゅうたく（きゅうもろぞふけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区北野町4-85-1他","lat":34.69983469,"lng":135.1870966,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造地上2階一部地下1階建、瓦葺、建築面積180㎡","structure_material":"木造地上2階一部地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"北野地区の西寄り、東西に長い敷地東端に建つ。木造2階1部地下1階建、建築面積180平方メートル、寄棟造スパニッシュ瓦葺。白色の外壁に、開口部のピンク色の鎧戸が映え、階段室には縦長のボゥウィンドウを設けるなど北野地区に調和した異国情緒を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009190"},{"id":"00009809","register_sub_id":"101","register_pk":"195638","name":"松宗蔵","kana":"まっそうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県高砂市高砂町字東浜町1252他","lat":34.74715897,"lng":134.8056807,"geo_status":"db","era":"文政6／平成19改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積59㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0567","desc":"堀川の西岸に位置し、土蔵造平屋建、切妻造本瓦葺で、西面に戸口を二所開け、本瓦葺の庇を付ける。西面腰上部と鉢巻を漆喰塗とする他は竪板を高く張り、小窓を穿つ。内部は一室で荷摺木を並べる。かつては海陸産物を納めた蔵で、舟運で栄えた高砂の面影を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009809"},{"id":"00004173","register_sub_id":"101","register_pk":"105163","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷477","lat":35.166702,"lng":134.792908,"geo_status":"db","era":"明治初期／大正期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積361㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0168","desc":"通りに東面して建つ木造２階建の店舗兼用住宅。棟の低い北側が切妻造・平入で明治初期，南側の寄棟造・妻入が大正期の増築。ともに２階の壁を塗籠めた重厚な外観であるが，窓廻りや出桁造の軒先廻りには年代差がみられ，生野の町家形式の変遷を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004173"},{"id":"00005310","register_sub_id":"101","register_pk":"106298","name":"松山大学温山記念会館表門","kana":"まつやまだいがくおんざんきねんかいかんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.73687462,"lng":135.37716217,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造、門柱4基、間口6.3m","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0220","desc":"西面敷地の西寄りに位置し，道路境から１１ｍ後退して建つ。門柱はＲＣ造で，間口６．３ｍの規模である。主柱は頂部を笠石状に造り，照明を付け，木製両開き扉を付ける。左右に主柱より太い脇柱を立て，それぞれに木製の片開き扉を付け，表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005310"},{"id":"00005308","register_sub_id":"101","register_pk":"106296","name":"松山大学温山記念会館倉庫","kana":"まつやまだいがくおんざんきねんかいかんそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.73707352,"lng":135.37735231,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積65㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0218","desc":"本館の北側に建ち，桁行８．１ｍ，梁間３．６ｍの規模で，ＲＣ造２階建，切妻造，スパニッシュ瓦葺とする。西面及び南面に庇付きの窓を開き，東側に下屋を張り出し出入口とする。周囲の床下及び軒下に換気口を設け，生活用品の倉庫として建設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005308"},{"id":"00005311","register_sub_id":"101","register_pk":"106299","name":"松山大学温山記念会館外塀","kana":"まつやまだいがくおんざんきねんかいかんそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.73661611,"lng":135.37772055,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、延長151m","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0221","desc":"敷地の東辺，北辺及び南辺の東方を囲うＲＣ造の塀で，壁面をモルタル塗洗出しとする。頂部を笠木状に造り，高さは２．２ｍから２ｍの範囲とする。東面に庭の北東にある防空壕の背面の出入口が開く。洋館の建つ敷地外周に相応しい景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005311"},{"id":"00005307","register_sub_id":"101","register_pk":"106295","name":"松山大学温山記念会館第二研修所","kana":"まつやまだいがくおんざんきねんかいかんだいにけんしゅうじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.73708004,"lng":135.37707983,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0217","desc":"西面敷地の北西隅に位置し，本館と道路の間に建つ。桁行４間，梁間３間半の規模で，木造平屋建，寄棟造，スパニッシュ瓦葺とし，南側に６畳間，３畳間，３畳大洋室を設け，北側に水回りをまとめる。使用人の住居として建てられ，本館の付属施設として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005307"},{"id":"00005309","register_sub_id":"101","register_pk":"106297","name":"松山大学温山記念会館防空壕","kana":"まつやまだいがくおんざんきねんかいかんぼうくうごう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.73698725,"lng":135.37795921,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、面積35㎡","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0219","desc":"敷地裏に当たる敷地東端に建ち，南北５．７ｍ，東西３．９ｍの規模で，西面南端及び南面東端に２重耐爆扉の出入口を設け，全体の壁厚を３０ｃｍとする。内部は１室で，室内の天井をドーム状として，鉄製の換気設備２箇所を設ける。防空壕の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005309"},{"id":"00005306","register_sub_id":"101","register_pk":"106294","name":"松山大学温山記念会館本館","kana":"まつやまだいがくおんざんきねんかいかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市甲子園口1-12-31","lat":34.736942,"lng":135.377472,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積582㎡、地下室付","structure_material":"鉄筋コンクリート造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"28 － 0216","desc":"西面敷地中央の北寄りに建ち，東西２０ｍ，南北１５ｍの規模で，ＲＣ造２階建，寄棟造，スパニッシュ瓦葺とする。表門からやや奥に建ち，正面に車廻しを付け，外観を洋風意匠でまとめ，堂々とした構えとする。昭和初期の有名建築家の建てた洋館として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005306"},{"id":"00005005","register_sub_id":"101","register_pk":"105995","name":"水口家住宅井戸屋","kana":"みずぐちけじゅうたくいどや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県川西市黒川字水口28","lat":34.92203489,"lng":135.45000645,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、建築面積3.5㎡","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0199","desc":"主屋の西方，屋敷地の西端に建つ。桁行２．０ｍ，梁間１．７ｍ規模の切妻造，桟瓦葺で，柱は角材，桁・梁・棟は丸太材を用い，柱に内転びを付け，石造井戸を覆う。蔵とともに主屋の前庭を囲う構成要素で，屋敷構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005005"},{"id":"00005004","register_sub_id":"101","register_pk":"105994","name":"水口家住宅蔵","kana":"みずぐちけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県川西市黒川字水口28","lat":34.92215544,"lng":135.45003673,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0198","desc":"主屋の北西方に位置する。桁行２間半，梁間２間規模，東西棟，切妻造，桟瓦葺，平入の２階建土蔵で，屋根は置屋根式とし，南面西寄りに庇を差し掛けて戸口を開ける。開口部は小さな丸窓のみで，北面は屋敷地北辺に廻る石垣とともに防御的な構えをとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005004"},{"id":"00005003","register_sub_id":"101","register_pk":"105993","name":"水口家住宅主屋","kana":"みずぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県川西市黒川字水口28","lat":34.92206186,"lng":135.45011497,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、茅葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"28 － 0197","desc":"能勢妙見山の麓に位置する。桁行７間，梁行４間半，南北棟，入母屋造，茅葺で，四周に桟瓦葺の庇を廻す。南方を土間とし，北方床上部を食い違い四間取とする。東北隅は座敷飾りを有する８畳のオクノマで長押を廻す。山間部の上流製炭農家の様相を今に伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005003"},{"id":"00008154","register_sub_id":"101","register_pk":"132595","name":"水田家住宅内蔵","kana":"みずたけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加西市北条町横尾字西門121他","lat":34.93340436,"lng":134.83774882,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0452","desc":"敷地の西辺に建ち、書院北面に接続する。桁行８．８ｍ梁間３．９ｍ、土蔵造２階建、切妻造桟瓦葺で、東面に庇を設け、縁板を張る。上下階とも南北二室に間仕切り、下階両室の東面を出入口として北室は腰を海鼠壁とする。丁寧なつくりになる土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008154"},{"id":"00008155","register_sub_id":"101","register_pk":"132596","name":"水田家住宅北蔵","kana":"みずたけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加西市北条町横尾字西門121他","lat":34.93348772,"lng":134.83785574,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積167㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0453","desc":"主屋の北側に建ち、桁行２１ｍ梁間５．９ｍ、土蔵造２階建、切妻造桟瓦葺で、南面に庇を設ける。東側四間半と西側六間分が別構造で、西側の棟がやや高く、木工品などの商品を納めたとされる。敷地背面を占める大型の土蔵で、商家の屋敷構えをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008155"},{"id":"00008152","register_sub_id":"101","register_pk":"132593","name":"水田家住宅主屋","kana":"みずたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加西市北条町横尾字西門121他","lat":34.93327389,"lng":134.83784305,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0450","desc":"旧丹波往来に南面し、桁行１５ｍ梁間１３ｍ、木造２階建、入母屋造桟瓦葺である。下階では東側の土間を出入口とし、西側は座敷で前面に格子をはめる。上階は漆喰で塗り込めて、東西端に袖卯建を付け、格子付の窓を穿つ。旧街道の面影を伝える町家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008152"},{"id":"00008153","register_sub_id":"101","register_pk":"132594","name":"水田家住宅書院","kana":"みずたけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加西市北条町横尾字西門121他","lat":34.93332825,"lng":134.83771983,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0451","desc":"主屋の西側に渡廊下を介して建ち、北側に内蔵を接続する。桁行７．９ｍ梁間５．７ｍ、木造平屋建、入母屋造桟瓦葺である。座敷二室の南・東面に縁をめぐらして庭を臨み、南室には座敷飾りを備える。縁の周囲にガラス戸をたて、開放的で軽快なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008153"},{"id":"00012427","register_sub_id":"101","register_pk":"531751","name":"武藤家住宅蔵","kana":"むとうけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区御影二丁目323-4","lat":34.72353056,"lng":135.2484,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積18㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-684","desc":"主屋の背面奥に建ち、蔵前を介して主屋と接続する。切妻造桟瓦葺、外壁モルタル塗で、入口に米国製錠前付の鋼製両開き扉、窓に鋼製扉を備え、内壁を竪板張で仕上げる。堅牢かつ上質なつくりで重厚な屋敷構えを構成するとともに良好な街路景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012427"},{"id":"00012426","register_sub_id":"101","register_pk":"531750","name":"武藤家住宅主屋","kana":"むとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区御影二丁目323-4","lat":34.72346111,"lng":135.2486,"geo_status":"db","era":"大正15年／昭和14年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺一部金属板葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"28-683","desc":"阪急御影駅近傍の閑静な住宅街にある。主屋は敷地中央に南面して建ち、入母屋屋根の周囲に下屋を廻し、西側奥に蔵前と離れ、東側奥に居間棟が附属する。東側中央に突出する玄関脇には洋館を附属する。優れた大工技術でまとめられた上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012426"},{"id":"00012428","register_sub_id":"101","register_pk":"531752","name":"武藤家住宅女中部屋","kana":"むとうけじゅうたくじょちゅうべや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区御影二丁目323-4","lat":34.72355,"lng":135.2485,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡、塀付","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"28-685","desc":"主屋の背面に中庭を挟んで建つ。切妻造桟瓦葺、外壁杉皮張で、内部は三畳一間、正面は渡廊下で主屋と接続し、東側面に井戸屋と塀を附属する。主屋と調和した丁寧かつ抑制の効いた造作が大工の技量を窺わせる。上流階級の生活の一端を伝える附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012428"},{"id":"00012429","register_sub_id":"101","register_pk":"531753","name":"武藤家住宅門","kana":"むとうけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市東灘区御影二丁目323-4","lat":34.72341111,"lng":135.2488,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺一部金属板葺、間口1.9m、左右袖壁及び東方潜戸付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"28-686","desc":"敷地の正面東端に建つ入母屋造の表門。本柱の背後に控柱を立て、茅葺風の急勾配屋根をかける。柱や梁は磨き丸太で、化粧軒裏に雑木の木舞や竹の隅木を用いるなど、主屋と異なる数寄屋風意匠とする。上流階級の暮らしぶりと同時に施主の趣向がよく現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012429"}];
